import sys,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from helper import setup,add,addm,run
setup('R 300.9','Störungen und Unregelmässigkeiten, Ziff.')
# ---- 1 Allgemeines
F="Für Rangierbewegungen im Bahnhof und in Anschlussgleisen werden die entsprechenden Befehle quittungspflichtig statt protokollpflichtig übermittelt. Hat der FDL keine Möglichkeit die Sicherungsanlage zu bedienen, darf ausnahmsweise die Person des zuständigen technischen Dienstes auf ausdrücklichen Auftrag des FDL notwendige Bedienungen ausführen."
add("1","Befehle Rangierbewegungen","Wie werden bei Störungen die Befehle für Rangierbewegungen im Bahnhof und in Anschlussgleisen gemäss § übermittelt?","Quittungspflichtig statt protokollpflichtig.",["Protokollpflichtig statt quittungspflichtig.","Mündlich ohne Quittung.","Schriftlich mit Unterschrift des RL."],F)
add("1","Bedienung technischer Dienst","Wann darf ausnahmsweise die Person des zuständigen technischen Dienstes gemäss § notwendige Bedienungen der Sicherungsanlage ausführen?","Wenn der FDL keine Möglichkeit hat, die Sicherungsanlage zu bedienen, auf ausdrücklichen Auftrag des FDL.",["Wenn der LF dies verlangt.","Bei jeder Störung an der Sicherungsanlage.","Sobald der technische Dienst vor Ort eintrifft."],F)
F="Das beteiligte Personal verständigt sich nötigenfalls gegenseitig über Unregelmässigkeiten, Verspätungen sowie Ergebnisse und Massnahmen. Bei Störungen mit Verspätungsfolgen sind die Reisenden über den Grund und soweit bekannt über die voraussichtliche Dauer bis zur Weiterfahrt zu informieren. Die Sicherheit der beteiligten Personen ist zu gewährleisten und sie sind auf mögliche Gefahren aufmerksam zu machen."
addm("1.1","Verständigung","Worüber verständigt sich das beteiligte Personal gemäss § nötigenfalls gegenseitig (Mehrfachauswahl).",["Unregelmässigkeiten","Verspätungen","Ergebnisse","Massnahmen"],["Fahrplanänderungen der Folgetage","Wetterprognosen"],F)
add("1.1","Information Reisende","Worüber sind die Reisenden bei Störungen mit Verspätungsfolgen gemäss § zu informieren?","Über den Grund und soweit bekannt über die voraussichtliche Dauer bis zur Weiterfahrt.",["Nur über die voraussichtliche Verspätung in Minuten.","Nur über Anschlussmöglichkeiten.","Nur über den Grund, nie über die Dauer."],F)
add("1.1","Sicherheit beteiligter Personen","Was ist gemäss § bezüglich der beteiligten Personen zu tun?","Ihre Sicherheit ist zu gewährleisten und sie sind auf mögliche Gefahren aufmerksam zu machen.",["Sie sind vom Ereignisort wegzuschicken.","Sie sind zur Mithilfe bei der Störungsbehebung zu verpflichten.","Sie sind nur nach Aufforderung zu informieren."],F)
F="Die Vollständigkeit einer Fahrt wird durch den LF für die eigene Fahrt oder den FDL vor Ort durch Beachten des Zugschlusssignals oder den RL bei Rangierbewegungen für die eigene Fahrt festgestellt. Dabei darf innerhalb des gestörten Abschnittes keine Änderung in der Formation der Triebfahrzeuge und der Anhängelast stattgefunden haben."
addm("1.2.1","Vollständigkeit feststellen","Wer kann die Vollständigkeit einer Fahrt gemäss § feststellen (Mehrfachauswahl).",["Der LF für die eigene Fahrt","Der FDL vor Ort durch Beachten des Zugschlusssignals","Der RL bei Rangierbewegungen für die eigene Fahrt"],["Der ZVB für jeden Zug","Der technische Dienst per Funk"],F)
add("1.2.1","Formation unverändert","Was darf innerhalb des gestörten Abschnittes für die Feststellung der Vollständigkeit gemäss § nicht stattgefunden haben?","Eine Änderung in der Formation der Triebfahrzeuge und der Anhängelast.",["Eine Änderung der Fahrplanlage.","Ein Wechsel des LF.","Ein Halt auf offener Strecke."],F)
F="Eine örtliche Kontrolle kann an folgenden Elementen der Sicherungsanlage durchgeführt werden: Weiche, überwachte Bahnübergangsanlage, GFM. Durch eine örtliche Kontrolle wird festgestellt, ob das gestörte Element der Sicherungsanlage frei ist. Bei Weichen sind alle Zweige bis zu den Enden der GFM zu kontrollieren. Damit sichergestellt ist, dass das richtige Element der Sicherungsanlage örtlich kontrolliert wird, übermittelt der FDL dem beauftragten Personal quittungspflichtig die notwendigen Angaben zur Lage des Abschnittes bzw. Elementes."
addm("1.2.2","Örtliche Kontrolle Elemente","An welchen Elementen der Sicherungsanlage kann gemäss § eine örtliche Kontrolle durchgeführt werden (Mehrfachauswahl).",["Weiche","Überwachte Bahnübergangsanlage","GFM"],["Hauptsignal","Block"],F)
add("1.2.2","Zweck örtliche Kontrolle","Was wird durch eine örtliche Kontrolle gemäss § festgestellt?","Ob das gestörte Element der Sicherungsanlage frei ist.",["Ob das gestörte Element beschädigt ist.","Ob der technische Dienst aufgeboten werden muss.","Ob die Fahrt auf Sicht aufgehoben werden kann."],F)
add("1.2.2","Kontrolle Weichen","Welche Bereiche sind bei einer örtlichen Kontrolle von Weichen gemäss § zu kontrollieren?","Alle Zweige bis zu den Enden der GFM.",["Nur der Weichenanfang.","Nur der abzweigende Strang.","Nur die Weichenzungen."],F)
add("1.2.2","Angaben zur Lage","Wie übermittelt der FDL dem beauftragten Personal gemäss § die Angaben zur Lage des Abschnittes bzw. Elementes?","Quittungspflichtig.",["Protokollpflichtig mit Befehl 1.","Mündlich ohne Quittung.","Mit Handzeichen."],F)
F="Kann der FDL die Störung nicht beheben bzw. wird die Grundstellung der Anlage auch durch Befahren nicht erreicht, hat der FDL den technischen Dienst aufzubieten."
add("1.2.3","Technischer Dienst aufbieten","Wann hat der FDL gemäss § den technischen Dienst aufzubieten?","Wenn er die Störung nicht beheben kann bzw. die Grundstellung auch durch Befahren nicht erreicht wird.",["Bei jeder Störung sofort.","Nur wenn eine Weiche betroffen ist.","Erst nach der dritten Fahrt."],F)
# ---- 2 Kernprozess
F="Geht ein Signal nicht auf Fahrt oder erreicht ein anderes Element der Sicherungsanlage den angestrebten Zustand nicht, hat der FDL davon auszugehen, dass eine Bedienung unterlassen wurde oder betriebliche Gründe die Fahrtstellung verhindern. Erst wenn feststeht, dass dies nicht zutrifft, kann von einer Störung ausgegangen werden. Als Elemente der Sicherungsanlage gelten insbesondere: Signal, Weiche, überwachte Bahnübergangsanlage, GFM, Block, Fahrstrassenverschluss."
add("2.1.1","Erste Annahme","Wovon hat der FDL gemäss § auszugehen, wenn ein Signal nicht auf Fahrt geht?","Dass eine Bedienung unterlassen wurde oder betriebliche Gründe die Fahrtstellung verhindern.",["Dass eine Störung am Signal vorliegt.","Dass der technische Dienst das Signal gesperrt hat.","Dass der LF das Signal nicht beachtet hat."],F)
add("2.1.1","Wann Störung","Ab wann kann gemäss § von einer Störung ausgegangen werden?","Erst wenn feststeht, dass keine unterlassene Bedienung und keine betrieblichen Gründe vorliegen.",["Sobald ein Signal nicht auf Fahrt geht.","Sobald der LF eine Störung meldet.","Nach einer Wartezeit von 5 Minuten."],F)
addm("2.1.1","Elemente Sicherungsanlage","Welche Elemente gelten gemäss § insbesondere als Elemente der Sicherungsanlage (Mehrfachauswahl).",["Signal","Weiche","Überwachte Bahnübergangsanlage","GFM","Block","Fahrstrassenverschluss"],["Fahrleitung","Zugschlusssignal"],F)
F="Haben die ersten Abklärungen ergeben, dass ein gestörtes Element der Sicherungsanlage vorliegt, ist dieses zu sichern."
add("2.1.2","Gestörtes Element sichern","Was ist gemäss § zu tun, wenn die ersten Abklärungen ein gestörtes Element der Sicherungsanlage ergeben haben?","Das gestörte Element ist zu sichern.",["Das Element ist sofort auszuschalten.","Das Element ist ersatzlos zu streichen.","Der Betrieb ist einzustellen."],F)
F="Die GFM darf durch den FDL mit einer Notbedienung in die Grundstellung verbracht werden, wenn mittels einer örtlichen Kontrolle festgestellt wurde, dass diese frei ist. Ist nach erfolgter Grundstellung die Störung behoben, dürfen die Sicherungsmassnahmen aufgehoben werden."
add("2.1.3","GFM Notbedienung","Unter welcher Voraussetzung darf der FDL eine gestörte GFM gemäss § mit einer Notbedienung in die Grundstellung verbringen?","Wenn mittels einer örtlichen Kontrolle festgestellt wurde, dass die GFM frei ist.",["Wenn der LF dies bestätigt.","Wenn der technische Dienst eingetroffen ist.","Wenn die letzte Fahrt vollständig war."],F)
add("2.1.3","GFM Sicherung aufheben","Wann dürfen bei einer gestörten GFM die Sicherungsmassnahmen gemäss § aufgehoben werden?","Wenn nach erfolgter Grundstellung die Störung behoben ist.",["Sobald die GFM frei ist.","Nach der ersten Fahrt über die GFM.","Nach 30 Minuten."],F)
F="Der FDL hat die letzte Fahrt über das gestörte Element der Sicherungsanlage und den für die nächste Fahrt gestörten Abschnitt zu bestimmen und zu protokollieren. Anschliessend hat der FDL zu prüfen, dass sich im bestimmten gestörten Abschnitt keine Fahrt befindet und dass keine Zustimmung zur Fahrt in den gestörten Abschnitt vorliegt."
addm("2.1.4","Massnahmen treffen","Was hat der FDL gemäss § zu bestimmen und zu protokollieren (Mehrfachauswahl).",["Die letzte Fahrt über das gestörte Element der Sicherungsanlage","Den für die nächste Fahrt gestörten Abschnitt"],["Die Höchstgeschwindigkeit im gestörten Abschnitt","Den LF der nächsten Fahrt"],F)
addm("2.1.4","Prüfung im gestörten Abschnitt","Was hat der FDL gemäss § anschliessend zu prüfen (Mehrfachauswahl).",["Dass sich im bestimmten gestörten Abschnitt keine Fahrt befindet","Dass keine Zustimmung zur Fahrt in den gestörten Abschnitt vorliegt"],["Dass der technische Dienst aufgeboten wurde","Dass alle Weichen im Abschnitt verschlossen sind"],F)
F="Der gestörte Abschnitt ist mit Fahrt auf Sicht zu befahren. Dabei hat der LF die überwachten Bahnübergangsanlagen als gestört zu betrachten. Ab der zweiten Fahrt besteht die Möglichkeit, den gestörten Abschnitt mit der vorgeschriebenen Höchstgeschwindigkeit zu befahren, sofern die entsprechenden Bedingungen für die Aufhebung der Fahrt auf Sicht erfüllt sind."
add("2.2","Fahrt auf Sicht gestörter Abschnitt","Wie ist der gestörte Abschnitt gemäss § grundsätzlich zu befahren?","Mit Fahrt auf Sicht.",["Mit höchstens 40 km/h.","Mit der vorgeschriebenen Höchstgeschwindigkeit.","Mit Schritttempo."],F)
add("2.2","Bahnübergangsanlagen gestört","Wie hat der LF die überwachten Bahnübergangsanlagen im gestörten Abschnitt gemäss § zu betrachten?","Als gestört.",["Als ausgeschaltet.","Als in Ordnung.","Als bewacht."],F)
add("2.2","Ab zweiter Fahrt","Ab welcher Fahrt besteht gemäss § die Möglichkeit, den gestörten Abschnitt mit der vorgeschriebenen Höchstgeschwindigkeit zu befahren?","Ab der zweiten Fahrt, sofern die Bedingungen für die Aufhebung der Fahrt auf Sicht erfüllt sind.",["Ab der ersten Fahrt, wenn der LF es verlangt.","Ab der dritten Fahrt in jedem Fall.","Erst nach Behebung der Störung."],F)
F="Besteht die betriebliche Notwendigkeit, hat die ISB in den Betriebsvorschriften die Bedingungen und das Vorgehen zur Aufhebung der Fahrt auf Sicht ab der zweiten Fahrt zu regeln. Der FDL hat zu prüfen, ob die letzte Fahrt den gestörten Abschnitt verlassen hat und deren Vollständigkeit festgestellt wurde und die durch die ISB in ihren Betriebsvorschriften festgelegten Vorgaben erfüllt sind. Sind in den Betriebsvorschriften der ISB keine Vorgaben zur Aufhebung der Fahrt auf Sicht ab der zweiten Fahrt enthalten, darf die Fahrt auf Sicht nicht aufgehoben werden."
add("2.2.1","Regelung Aufhebung","Wer regelt gemäss § die Bedingungen zur Aufhebung der Fahrt auf Sicht ab der zweiten Fahrt?","Die ISB in den Betriebsvorschriften.",["Das BAV.","Das EVU.","Der FDL im Einzelfall."],F)
addm("2.2.1","FDL prüft Aufhebung","Was hat der FDL vor der Aufhebung der Fahrt auf Sicht ab der zweiten Fahrt gemäss § zu prüfen (Mehrfachauswahl).",["Dass die letzte Fahrt den gestörten Abschnitt verlassen hat","Dass die Vollständigkeit der letzten Fahrt festgestellt wurde","Dass die in den Betriebsvorschriften der ISB festgelegten Vorgaben erfüllt sind"],["Dass der technische Dienst die Störung beurteilt hat","Dass alle Bahnübergangsanlagen ausgeschaltet sind"],F)
add("2.2.1","Keine Vorgaben ISB","Was gilt gemäss §, wenn die Betriebsvorschriften der ISB keine Vorgaben zur Aufhebung der Fahrt auf Sicht ab der zweiten Fahrt enthalten?","Die Fahrt auf Sicht darf nicht aufgehoben werden.",["Die Fahrt auf Sicht darf vom FDL frei aufgehoben werden.","Die Fahrt auf Sicht darf mit höchstens 40 km/h aufgehoben werden.","Die Fahrt auf Sicht entfällt ab der dritten Fahrt."],F)
F="Der FDL hat den Fahrweg soweit möglich einzustellen und zu sichern."
add("2.3.1","Fahrweg einstellen","Was hat der FDL gemäss § mit dem Fahrweg soweit möglich zu tun?","Ihn einzustellen und zu sichern.",["Ihn zu sperren.","Ihn zu kontrollieren.","Ihn dem LF zu beschreiben."],F)
F="Die GFM eines Gleises oder der Block darf nach dem protokollpflichtigen Vorschreiben von Fahrt auf Sicht für die nächste Fahrt in die Grundstellung verbracht werden. Auf das Vorschreiben von Fahrt auf Sicht für die nächste Fahrt kann verzichtet werden, wenn die Vorgaben für die Aufhebung der Fahrt auf Sicht ab der zweiten Fahrt erfüllt sind."
add("2.3.2","GFM Gleis oder Block","Wann darf die GFM eines Gleises oder der Block gemäss § in die Grundstellung verbracht werden?","Nach dem protokollpflichtigen Vorschreiben von Fahrt auf Sicht für die nächste Fahrt.",["Nach einer örtlichen Kontrolle durch den LF.","Nach dem quittungspflichtigen Vorschreiben von Halt.","Sofort nach Feststellen der Störung."],F)
add("2.3.2","Verzicht Fahrt auf Sicht","Wann kann gemäss § auf das Vorschreiben von Fahrt auf Sicht für die nächste Fahrt verzichtet werden?","Wenn die Vorgaben für die Aufhebung der Fahrt auf Sicht ab der zweiten Fahrt erfüllt sind.",["Wenn der LF die Strecke kennt.","Wenn die Störung nur den Block betrifft.","Wenn der technische Dienst vor Ort ist."],F)
F="Wenn mittels örtlicher Kontrolle festgestellt wurde, dass die Weiche frei ist, darf diese mit der Notbedienung umgestellt werden."
add("2.3.3","Weiche trotz Belegung","Unter welcher Voraussetzung darf eine Weiche trotz angezeigter Belegung gemäss § mit der Notbedienung umgestellt werden?","Wenn mittels örtlicher Kontrolle festgestellt wurde, dass die Weiche frei ist.",["Wenn der LF die Weiche als frei meldet.","Wenn die Weiche verschlossen ist.","Wenn der technische Dienst zugestimmt hat."],F)
F="Die Zustimmung wird wie folgt erteilt: mit Fahrtstellung des Hauptsignals oder mit Fahrtstellung des Hauptsignals durch eine Notbedienung oder mit dem Hauptsignal gestörte Bahnübergangsanlage oder mit dem Hilfssignal oder mit dem protokollpflichtigen Befehl 1 oder auf Strecken ohne Hauptsignale ist das Vorgehen durch die ISB festzulegen."
addm("2.4.1","Zustimmung bei Zügen","Wie kann die Zustimmung bei Zügen gemäss § erteilt werden (Mehrfachauswahl).",["Mit Fahrtstellung des Hauptsignals","Mit Fahrtstellung des Hauptsignals durch eine Notbedienung","Mit dem Hauptsignal gestörte Bahnübergangsanlage","Mit dem Hilfssignal","Mit dem protokollpflichtigen Befehl 1"],["Mit dem quittungspflichtigen Befehl 9","Mit einem Handzeichen des FDL"],F)
add("2.4.1","Strecken ohne Hauptsignale","Wer legt gemäss § das Vorgehen für die Zustimmung auf Strecken ohne Hauptsignale fest?","Die ISB.",["Der FDL.","Das EVU.","Der technische Dienst."],F)
F="Wird das Hauptsignal mit einer Notbedienung auf Fahrt gestellt, hat der FDL der nächsten Fahrt vor dem auf Fahrt stellen des Hauptsignals die Fahrt auf Sicht protokollpflichtig mit dem Befehl 6 vorzuschreiben, ausgenommen die Vorgaben für die Aufhebung der Fahrt auf Sicht ab der zweiten Fahrt sind erfüllt."
add("2.4.2","Notbedienung Befehl 6","Mit welchem Befehl schreibt der FDL der nächsten Fahrt gemäss § die Fahrt auf Sicht vor, wenn das Hauptsignal mit einer Notbedienung auf Fahrt gestellt wird?","Protokollpflichtig mit dem Befehl 6.",["Quittungspflichtig mit dem Befehl 1.","Protokollpflichtig mit dem Befehl 9.","Quittungspflichtig mit dem Befehl 6."],F)
add("2.4.2","Zeitpunkt Befehl 6","Wann hat der FDL die Fahrt auf Sicht gemäss § vorzuschreiben, wenn das Hauptsignal mit einer Notbedienung auf Fahrt gestellt wird?","Vor dem auf Fahrt stellen des Hauptsignals.",["Nach dem auf Fahrt stellen des Hauptsignals.","Erst bei der Vorbeifahrt am Signal.","Nach Eintreffen des technischen Dienstes."],F)
F="Mit dem Hilfssignal bzw. mit dem protokollpflichtigen Befehl 1 erteilt der FDL dem LF die Zustimmung, am betreffenden Hauptsignal vorbeizufahren. Das Hilfssignal bzw. der protokollpflichtige Befehl 1 erlaubt ebenfalls die Vorbeifahrt an unbeleuchteten und Halt zeigenden Zwergsignalen. Bis zum nächsten Hauptsignal ist mit Fahrt auf Sicht zu fahren. Am nächsten Hauptsignal ist Halt zu erwarten. Wird gleichzeitig eine Einfahrt in ein besetztes Gleis vollzogen, braucht es keine zusätzliche Verständigung des LF. Muss weiter als bis zum nächsten Fahrt zeigenden Hauptsignal mit Fahrt auf Sicht gefahren werden, ist dies dem LF protokollpflichtig mit dem Befehl 6 vorzuschreiben. Erlischt das Hilfssignal bevor die Zugspitze daran vorbeigefahren ist, hat der LF den Zug sofort anzuhalten und mit dem FDL Kontakt aufzunehmen."
addm("2.4.3","Hilfssignal Wirkung","Was erlauben das Hilfssignal bzw. der protokollpflichtige Befehl 1 gemäss § (Mehrfachauswahl).",["Die Vorbeifahrt am betreffenden Hauptsignal","Die Vorbeifahrt an unbeleuchteten Zwergsignalen","Die Vorbeifahrt an Halt zeigenden Zwergsignalen"],["Die Fahrt mit der vorgeschriebenen Höchstgeschwindigkeit","Die Vorbeifahrt an allen weiteren Hauptsignalen"],F)
add("2.4.3","Fahrt auf Sicht bis","Wie ist nach der Vorbeifahrt am Hilfssignal bzw. mit Befehl 1 gemäss § bis zum nächsten Hauptsignal zu fahren?","Mit Fahrt auf Sicht.",["Mit höchstens 40 km/h.","Mit der vorgeschriebenen Höchstgeschwindigkeit.","Mit Schritttempo."],F)
add("2.4.3","Am nächsten Hauptsignal","Was ist gemäss § am nächsten Hauptsignal nach der Vorbeifahrt am Hilfssignal zu erwarten?","Halt.",["Fahrt.","Warnung.","Fahrt mit Vorsicht."],F)
add("2.4.3","Einfahrt besetztes Gleis","Was gilt gemäss §, wenn gleichzeitig eine Einfahrt in ein besetztes Gleis vollzogen wird?","Es braucht keine zusätzliche Verständigung des LF.",["Der LF ist protokollpflichtig zu verständigen.","Der LF ist quittungspflichtig zu verständigen.","Die Einfahrt ist nicht zulässig."],F)
add("2.4.3","Fahrt auf Sicht weiter","Wie ist dem LF gemäss § vorzuschreiben, dass weiter als bis zum nächsten Fahrt zeigenden Hauptsignal mit Fahrt auf Sicht gefahren werden muss?","Protokollpflichtig mit dem Befehl 6.",["Quittungspflichtig mit dem Befehl 6.","Protokollpflichtig mit dem Befehl 1.","Mündlich ohne Befehl."],F)
add("2.4.3","Hilfssignal erlischt","Was hat der LF gemäss § zu tun, wenn das Hilfssignal erlischt, bevor die Zugspitze daran vorbeigefahren ist?","Den Zug sofort anhalten und mit dem FDL Kontakt aufnehmen.",["Mit Fahrt auf Sicht weiterfahren.","Mit der vorgeschriebenen Höchstgeschwindigkeit weiterfahren.","Bis zum nächsten Bahnhof weiterfahren."],F)
F="Der FDL erteilt dem RL quittungspflichtig den Befehl am Halt zeigenden Zwerg- bzw. Rangiersignal vorbeizufahren. Der Befehl ist für jede Fahrt einzeln zu erteilen."
add("2.4.4","Rangierbewegung im Bahnhof","Wie erteilt der FDL dem RL gemäss § den Befehl, am Halt zeigenden Zwerg- bzw. Rangiersignal vorbeizufahren?","Quittungspflichtig, für jede Fahrt einzeln.",["Protokollpflichtig, einmalig für alle Fahrten.","Quittungspflichtig, einmalig für alle Fahrten.","Mündlich ohne Quittung, für jede Fahrt einzeln."],F)
F="Vor dem Erteilen der Zustimmung in den gestörten Abschnitt, hat der FDL der nächsten Rangierbewegung auf die Strecke die Fahrt auf Sicht protokollpflichtig mit dem Befehl 6 vorzuschreiben, ausgenommen die Vorgaben für die Aufhebung der Fahrt auf Sicht ab der zweiten Fahrt sind erfüllt."
add("2.4.5","Rangierbewegung auf Strecke","Was hat der FDL der nächsten Rangierbewegung auf die Strecke gemäss § vor dem Erteilen der Zustimmung in den gestörten Abschnitt vorzuschreiben?","Die Fahrt auf Sicht protokollpflichtig mit dem Befehl 6.",["Die Fahrt auf Sicht quittungspflichtig mit dem Befehl 1.","Halt vor dem gestörten Abschnitt.","Schritttempo quittungspflichtig."],F)
F="Vor dem Erteilen der Zustimmung in den gestörten Abschnitt, verständigt der FDL den SC protokollpflichtig, dass die Fahrt auf Sicht für die betreffenden Rangierbewegungen nicht aufgehoben werden darf."
add("2.4.6","Rangierbewegung gesperrte Gleise","Was teilt der FDL dem SC gemäss § vor dem Erteilen der Zustimmung in den gestörten Abschnitt protokollpflichtig mit?","Dass die Fahrt auf Sicht für die betreffenden Rangierbewegungen nicht aufgehoben werden darf.",["Dass das Gleis wieder freigegeben ist.","Dass die Rangierbewegungen mit Höchstgeschwindigkeit verkehren dürfen.","Dass die Arbeitsstelle zu räumen ist."],F)
F="Ist sichergestellt, dass die Fahrt den gestörten Abschnitt oder einen Teil des gestörten Abschnittes befahren und wieder verlassen hat, dürfen die entsprechenden Sicherungsmassnahmen, welche speziell für diese Fahrt getroffen wurden, aufgehoben werden."
add("2.5","Aufheben nach Fahrt","Wann dürfen die Sicherungsmassnahmen, die speziell für eine Fahrt getroffen wurden, gemäss § aufgehoben werden?","Wenn sichergestellt ist, dass die Fahrt den gestörten Abschnitt oder einen Teil davon befahren und wieder verlassen hat.",["Sobald die Fahrt abgefahren ist.","Sobald die Störung gemeldet wurde.","Nach 30 Minuten."],F)
F="Liegt kein gestörter Abschnitt mehr vor, hat der FDL die Vollständigkeit der Fahrt, welche den gestörten Abschnitt zuletzt befahren und wieder verlassen hat, festzustellen. Sind durchgehend dauernd aktive GFM vorhanden, kann auf die Feststellung der Vollständigkeit des letzten Zuges verzichtet werden, sofern die nächste Fahrt als Zug verkehrt und das Hauptsignal ohne Notbedienung auf Fahrt gestellt werden kann. Die Sicherungsmassnahmen, welche für den gestörten Abschnitt getroffen wurden, dürfen aufgehoben werden."
add("2.6","Abschluss Störung","Was hat der FDL gemäss § festzustellen, wenn kein gestörter Abschnitt mehr vorliegt?","Die Vollständigkeit der Fahrt, welche den gestörten Abschnitt zuletzt befahren und wieder verlassen hat.",["Die Vollständigkeit aller Fahrten seit Störungsbeginn.","Die Funktion aller Signale des Abschnitts.","Die Anzahl der betroffenen Reisenden."],F)
addm("2.6","Verzicht Vollständigkeit","Unter welchen Bedingungen kann gemäss § auf die Feststellung der Vollständigkeit des letzten Zuges verzichtet werden (Mehrfachauswahl).",["Es sind durchgehend dauernd aktive GFM vorhanden","Die nächste Fahrt verkehrt als Zug","Das Hauptsignal kann ohne Notbedienung auf Fahrt gestellt werden"],["Die letzte Fahrt war ein Güterzug","Der technische Dienst hat die Störung behoben"],F)
# ---- 3 Signale
F="Muss an mehreren aufeinander folgenden Halt zeigenden Signalen vorbeigefahren werden, darf dies mit einem einzigen Befehl 1 vorgeschrieben werden. Das erste und das letzte Signal, an welchen bei Halt vorbeigefahren werden muss, sind eindeutig zu bezeichnen. Ist die zu befahrende Strecke mehrspurig, ist zusätzlich das Streckengleis zu bezeichnen, auf welchem der Zug verkehren muss (z.B. linkes Gleis)."
add("3.1","Mehrere Halt zeigende Signale","Wie darf die Vorbeifahrt an mehreren aufeinander folgenden Halt zeigenden Signalen gemäss § vorgeschrieben werden?","Mit einem einzigen Befehl 1.",["Mit je einem Befehl 1 pro Signal.","Mit einem einzigen Befehl 6.","Mit einem quittungspflichtigen Befehl 9."],F)
addm("3.1","Befehl 1 Angaben","Was ist im Befehl 1 für die Vorbeifahrt an mehreren Halt zeigenden Signalen gemäss § anzugeben (Mehrfachauswahl).",["Das erste Signal, an welchem bei Halt vorbeigefahren werden muss","Das letzte Signal, an welchem bei Halt vorbeigefahren werden muss","Bei mehrspurigen Strecken das Streckengleis, auf dem der Zug verkehren muss"],["Die Anzahl der Reisenden im Zug","Die Zeit der voraussichtlichen Weiterfahrt"],F)
F="Bleibt nach erfolgter Zugfahrt ein Hauptsignal auf Fahrt oder bleibt ein Hilfssignal oder ein Hauptsignal gestörte Bahnübergangsanlage beleuchtet, muss der FDL das Signal manuell in die Grundstellung verbringen."
add("3.2","Hauptsignal bleibt auf Fahrt","Was muss der FDL gemäss § tun, wenn nach erfolgter Zugfahrt ein Hauptsignal auf Fahrt bleibt?","Das Signal manuell in die Grundstellung verbringen.",["Das Signal bis zur nächsten Fahrt belassen.","Den LF der nächsten Fahrt quittungspflichtig verständigen.","Den technischen Dienst aufbieten und das Signal belassen."],F)
addm("3.2","Beleuchtet bleibende Signale","Bei welchen Signalen muss der FDL gemäss § nach erfolgter Zugfahrt manuell die Grundstellung herstellen (Mehrfachauswahl).",["Hauptsignal bleibt auf Fahrt","Hilfssignal bleibt beleuchtet","Hauptsignal gestörte Bahnübergangsanlage bleibt beleuchtet"],["Vorsignal zeigt Warnung","Zwergsignal zeigt Halt"],F)
F="Fällt ein Hauptsignal vorzeitig auf Halt zurück, hat der LF den Zug sofort anzuhalten und mit dem FDL Kontakt aufzunehmen. Kommt der Zug nach dem Signal zum Stillstand, genügt eine quittungspflichtige Zustimmung des FDL an den LF für die Weiterfahrt."
add("3.3","Vorzeitig auf Halt","Was hat der LF gemäss § zu tun, wenn ein Hauptsignal vorzeitig auf Halt zurückfällt?","Den Zug sofort anhalten und mit dem FDL Kontakt aufnehmen.",["Mit Fahrt auf Sicht weiterfahren.","Bis zum nächsten Hauptsignal weiterfahren.","Den Zug erst im nächsten Bahnhof anhalten."],F)
add("3.3","Stillstand nach Signal","Was genügt gemäss §, wenn der Zug nach dem vorzeitig auf Halt zurückgefallenen Hauptsignal zum Stillstand kommt?","Eine quittungspflichtige Zustimmung des FDL an den LF für die Weiterfahrt.",["Ein protokollpflichtiger Befehl 1.","Eine mündliche Zustimmung ohne Quittung.","Ein Hilfssignal."],F)
F="Kann ein Sperrsignal nicht dunkel geschaltet werden, ist der LF bzw. RL durch den FDL quittungspflichtig über die Vorbeifahrt am Halt zeigenden Sperrsignal zu verständigen."
add("3.4","Sperrsignal","Was ist gemäss § zu tun, wenn ein Sperrsignal nicht dunkel geschaltet werden kann?","Der LF bzw. RL ist durch den FDL quittungspflichtig über die Vorbeifahrt am Halt zeigenden Sperrsignal zu verständigen.",["Der LF bzw. RL ist protokollpflichtig mit Befehl 1 zu verständigen.","Der Zug darf nicht weiterfahren.","Der LF bzw. RL fährt mit Fahrt auf Sicht ohne Verständigung."],F)
F="Stellt der LF nach Vorbeifahrt an einem Fahrt zeigenden Vorsignal einen dunklen Fahrtstellungsmelder fest und wurde der LF darüber nicht verständigt, hat der LF den Zug anzuhalten und mit dem zuständigen FDL Kontakt aufzunehmen. Am zugehörigen Hauptsignal ist Halt zu erwarten. Kann der FDL einen gestörten Fahrtstellungsmelder feststellen, hat der FDL den LF quittungspflichtig darüber zu verständigen."
add("3.5","Dunkler Fahrtstellungsmelder","Was hat der LF gemäss § zu tun, wenn er nach Vorbeifahrt an einem Fahrt zeigenden Vorsignal einen dunklen Fahrtstellungsmelder feststellt und nicht verständigt wurde?","Den Zug anhalten und mit dem zuständigen FDL Kontakt aufnehmen.",["Mit Fahrt auf Sicht bis zum Hauptsignal weiterfahren.","Mit der vorgeschriebenen Höchstgeschwindigkeit weiterfahren.","Die Störung nach Abschluss der Fahrt melden."],F)
add("3.5","Halt erwarten","Was ist gemäss § am zugehörigen Hauptsignal zu erwarten, wenn der Fahrtstellungsmelder dunkel ist?","Halt.",["Fahrt.","Warnung.","Fahrt mit Vorsicht."],F)
add("3.5","FDL Fahrtstellungsmelder","Wie hat der FDL den LF gemäss § zu verständigen, wenn er einen gestörten Fahrtstellungsmelder feststellen kann?","Quittungspflichtig.",["Protokollpflichtig.","Mündlich ohne Quittung.","Gar nicht."],F)
F="Stellt der LF bzw. der RL in der Fahrstrasse ein nicht oder nur mit einer der beiden unteren Lampen beleuchtetes Zwergsignal fest und wurde der LF darüber nicht verständigt, hat der LF den Zug bzw. die Rangierbewegung anzuhalten und mit dem zuständigen FDL Kontakt aufzunehmen. Der FDL erteilt dem LF bzw. dem RL quittungspflichtig die Zustimmung zur Weiterfahrt. Leuchtet an einem Zwergsignal nur die obere Lampe, ist das Signalbild als Fahrt mit Vorsicht zu betrachten. Kann der FDL feststellen, welches Zwergsignal gestört ist, hat der FDL den LF bzw. den RL quittungspflichtig darüber zu verständigen."
add("3.6","Unklares Zwergsignal","Was hat der LF bzw. RL gemäss § zu tun, wenn ein Zwergsignal nicht oder nur mit einer der beiden unteren Lampen beleuchtet ist und er nicht verständigt wurde?","Den Zug bzw. die Rangierbewegung anhalten und mit dem zuständigen FDL Kontakt aufnehmen.",["Mit Fahrt auf Sicht weiterfahren.","Das Signalbild als Fahrt mit Vorsicht betrachten.","Mit Schritttempo weiterfahren."],F)
add("3.6","Zwergsignal Zustimmung","Wie erteilt der FDL dem LF bzw. RL gemäss § die Zustimmung zur Weiterfahrt am unklaren Zwergsignal?","Quittungspflichtig.",["Protokollpflichtig mit Befehl 1.","Protokollpflichtig mit Befehl 6.","Mündlich ohne Quittung."],F)
add("3.6","Obere Lampe","Wie ist das Signalbild gemäss § zu betrachten, wenn an einem Zwergsignal nur die obere Lampe leuchtet?","Als Fahrt mit Vorsicht.",["Als Halt.","Als Fahrt.","Als gestörtes Signal ohne Bedeutung."],F)
F="Bis zur Behebung der Störung am Signal für Bedarfshalt hat der FDL den betreffenden Zügen quittungspflichtig einen Halt vorzuschreiben. Bei einem Defekt an der Haltanforderung im Zug ist bei jeder Haltestelle oder in jedem Bahnhof mit Bedarfshalt anzuhalten."
add("3.7","Signal Bedarfshalt","Was hat der FDL den betreffenden Zügen gemäss § bis zur Behebung der Störung am Signal für Bedarfshalt vorzuschreiben?","Quittungspflichtig einen Halt.",["Protokollpflichtig die Durchfahrt.","Quittungspflichtig Fahrt auf Sicht.","Protokollpflichtig Befehl 6."],F)
add("3.7","Defekte Haltanforderung","Was gilt gemäss § bei einem Defekt an der Haltanforderung im Zug?","Bei jeder Haltestelle oder in jedem Bahnhof mit Bedarfshalt ist anzuhalten.",["Es ist nur auf Verlangen der Reisenden anzuhalten.","Es ist an keiner Haltestelle mit Bedarfshalt anzuhalten.","Es ist nur im nächsten Bahnhof anzuhalten."],F)
F="Kann ein Lichtsignal für Schutzstrecken (auch das Vorsignal), bei ausgeschalteter Schutzstrecke oder ein Stromabnehmersignal oder ein Zonen-Schutzstreckensignal oder ein Systemwechselsignal nicht beleuchtet werden, hat der FDL den LF quittungspflichtig zu verständigen."
addm("3.8","Signale elektrischer Betrieb","Bei welchen nicht beleuchtbaren Lichtsignalen hat der FDL den LF gemäss § quittungspflichtig zu verständigen (Mehrfachauswahl).",["Schutzstrecken (auch das Vorsignal) bei ausgeschalteter Schutzstrecke","Stromabnehmersignal","Zonen-Schutzstreckensignal","Systemwechselsignal"],["Zwergsignal","Haltsignal für Bedarfshalt"],F)
add("3.8","Verständigung Signale elektrischer Betrieb","Wie hat der FDL den LF gemäss § zu verständigen, wenn ein Lichtsignal für den elektrischen Betrieb nicht beleuchtet werden kann?","Quittungspflichtig.",["Protokollpflichtig.","Mündlich ohne Quittung.","Mit Befehl 6."],F)
# ---- 4 Weichen
F="Weichen mit zweifelhafter Anzeige der Lage oder Weichen, die sich nicht in Endlage befinden, dürfen nicht befahren werden."
addm("4.1","Weichen nicht befahren","Welche Weichen dürfen gemäss § nicht befahren werden (Mehrfachauswahl).",["Weichen mit zweifelhafter Anzeige der Lage","Weichen, die sich nicht in Endlage befinden"],["Weichen mit Handverschluss","Weichen in Nebengleisen"],F)
F="In Fahrstrassen werden die Weichen verschlossen. Kann eine Weiche durch die Fahrstrasse nicht verschlossen werden, ist die Fahrtstellung der zugehörigen Signale nicht möglich. Die Weichen müssen in diesem Fall soweit möglich apparatemässig gegen unbeabsichtigtes Umstellen gesichert werden."
add("4.2","Fehlender Verschluss","Was ist gemäss § die Folge, wenn eine Weiche durch die Fahrstrasse nicht verschlossen werden kann?","Die Fahrtstellung der zugehörigen Signale ist nicht möglich.",["Die Signale zeigen Fahrt mit Vorsicht.","Die Signale zeigen Fahrt, die Weiche ist örtlich zu sichern.","Die Signale erlöschen."],F)
add("4.2","Sichern ohne Verschluss","Wie müssen Weichen ohne möglichen Verschluss gemäss § soweit möglich gesichert werden?","Apparatemässig gegen unbeabsichtigtes Umstellen.",["Mit Hemmschuhen.","Mit Handverschluss durch den LF.","Gar nicht, da die Signale auf Halt bleiben."],F)
F="Können Weichen nicht, oder Weichen mit Drahtzügen oder Gestänge nur mit aussergewöhnlicher Kraftanstrengung in die Endlage gebracht werden, sind sie sofort in die ursprüngliche Lage zurückzustellen."
add("4.3.1","Weiche nicht umstellbar","Was ist gemäss § zu tun, wenn Weichen nicht oder nur mit aussergewöhnlicher Kraftanstrengung in die Endlage gebracht werden können?","Sie sind sofort in die ursprüngliche Lage zurückzustellen.",["Sie sind mit Gewalt umzustellen.","Sie sind in der erreichten Lage zu belassen.","Sie sind zu verkeilen."],F)
F="Insbesondere folgende Ursachen können das Umstellen einer Weiche verhindern: Hindernis / Schmutz, Weiche verschlossen, GFM trotz freiem Zustand belegt, Stromversorgung unterbrochen, andere Defekte an der Weiche."
addm("4.3.2","Ursachen Umstellen","Welche Ursachen können das Umstellen einer Weiche gemäss § insbesondere verhindern (Mehrfachauswahl).",["Hindernis oder Schmutz","Weiche verschlossen","GFM trotz freiem Zustand belegt","Stromversorgung unterbrochen","Andere Defekte an der Weiche"],["Zu hohe Geschwindigkeit der letzten Fahrt","Dunkles Zugschlusssignal"],F)
F="Der Verschluss darf aufgelöst werden, wenn sich kein Fahrzeug gegen die Weiche bewegt und kein Signal und keine Zustimmung eine Fahrt über die Weiche erlaubt."
addm("4.3.3","Weiche verschlossen","Unter welchen Bedingungen darf der Verschluss einer Weiche gemäss § aufgelöst werden (Mehrfachauswahl).",["Es bewegt sich kein Fahrzeug gegen die Weiche","Kein Signal erlaubt eine Fahrt über die Weiche","Keine Zustimmung erlaubt eine Fahrt über die Weiche"],["Die Weiche wurde bereits befahren","Der technische Dienst ist aufgeboten"],F)
F="Ist die Stromversorgung unterbrochen, sind die Sicherungen zu kontrollieren und nötigenfalls zu ersetzen. Auch die Überstromautomaten sind zu kontrollieren und allenfalls einzuschalten. Bleiben diese Massnahmen erfolglos, ist die Weiche so zu sichern, dass sie bei Wiedereinschaltung der Stromversorgung nicht umlaufen kann. Die Weiche darf mit der Kurbel umgestellt werden."
addm("4.3.4","Stromversorgung unterbrochen","Welche Massnahmen sind bei unterbrochener Stromversorgung einer Weiche gemäss § zu treffen (Mehrfachauswahl).",["Die Sicherungen kontrollieren und nötigenfalls ersetzen","Die Überstromautomaten kontrollieren und allenfalls einschalten","Bei erfolglosen Massnahmen die Weiche so sichern, dass sie bei Wiedereinschaltung nicht umlaufen kann"],["Die Weiche mit dem Fuss umstellen","Die Stromversorgung des ganzen Bahnhofs abschalten"],F)
add("4.3.4","Weiche Kurbel","Womit darf eine Weiche bei erfolglos gebliebenen Massnahmen gemäss § umgestellt werden?","Mit der Kurbel.",["Mit dem Weichenstelleisen.","Mit der Notbedienung am Stellwerk.","Mit einem Keil."],F)
F="Kann die Weiche auch mit der Kurbel nicht umgestellt werden, ist nach den Weisungen des zuständigen technischen Dienstes zu verfahren."
add("4.3.5","Andere Defekte","Wonach ist gemäss § zu verfahren, wenn die Weiche auch mit der Kurbel nicht umgestellt werden kann?","Nach den Weisungen des zuständigen technischen Dienstes.",["Nach den Weisungen des LF.","Nach den Betriebsvorschriften des EVU.","Nach Ermessen des FDL."],F)
F="Wird für einen nicht besetzten Bahnhof protokollpflichtig die Vorbeifahrt an Halt zeigenden Signalen vorgeschrieben und ist die Weichenstellung durch den FDL nicht feststellbar, hat der FDL vor der betreffenden Weiche bzw. Weichengruppe quittungspflichtig einen Halt anzuordnen. Der LF hat die betreffende Weiche bzw. Weichengruppe auf Fremdkörper und mechanische Schäden sowie die richtige Stellung zu kontrollieren. Wurden die richtige Stellung der Weichen und keine Schäden festgestellt, darf nach Rücksprache mit dem FDL weitergefahren werden. Nachfolgende Züge dürfen die Weichen ohne Halt befahren."
add("4.4","Weichenstellung nicht feststellbar","Was hat der FDL gemäss § anzuordnen, wenn bei einem nicht besetzten Bahnhof die Vorbeifahrt an Halt zeigenden Signalen vorgeschrieben wird und die Weichenstellung nicht feststellbar ist?","Quittungspflichtig einen Halt vor der betreffenden Weiche bzw. Weichengruppe.",["Protokollpflichtig die Weiterfahrt mit Fahrt auf Sicht.","Quittungspflichtig die Durchfahrt mit 40 km/h.","Protokollpflichtig die Umleitung."],F)
addm("4.4","LF kontrolliert Weiche","Was hat der LF gemäss § an der betreffenden Weiche bzw. Weichengruppe zu kontrollieren (Mehrfachauswahl).",["Fremdkörper","Mechanische Schäden","Die richtige Stellung"],["Die Stromversorgung","Die Funktion der GFM"],F)
add("4.4","Nachfolgende Züge","Wie dürfen nachfolgende Züge gemäss § die Weichen befahren, wenn die Kontrolle keine Mängel ergeben hat?","Ohne Halt.",["Ebenfalls nach Halt und Kontrolle durch den LF.","Nur mit Fahrt auf Sicht.","Nur mit Zustimmung des technischen Dienstes."],F)
F="Die Endlage einer Weiche wird elektrisch überwacht. Fehlt die Überwachung, können die zugehörigen Signale nicht auf Fahrt gestellt werden. Der FDL kann technisches oder fahrdienstliches Personal mit der örtlichen Kontrolle der korrekten Endlage beauftragen. Die Weiche ist dabei auf Fremdkörper und mechanische Schäden zu kontrollieren. Die Kontrolle ist zu wiederholen bei Fahrt von der Wurzel aus nach jedem Umstellen der Weiche, bei Fahrt gegen die Spitze vor jeder Fahrt. Ist die Weiche mechanisch nicht in der Endlage, beschädigt oder ist der Befund unklar, darf sie nicht mehr befahren werden. Das weitere Vorgehen richtet sich nach den Weisungen des zuständigen technischen Dienstes. Wird die örtliche Weichenkontrolle Personal auf dem Zug übertragen, hat der FDL dem LF quittungspflichtig einen Halt vor der Weiche vorzuschreiben und ihn mit der Kontrolle der Weiche zu beauftragen. Danach darf die Zustimmung bzw. der protokollpflichtige Befehl 1 erteilt werden. Wurde die Weiche durch örtliche Kontrolle als in Ordnung befunden und muss sie bei fehlender Überwachung befahren werden, ist sie in die entsprechende Lage zu verbringen und gegen unzeitiges Umstellen zu sichern. Bis die Weiche vom zuständigen technischen Dienst kontrolliert worden ist, sind folgende Höchstgeschwindigkeiten protokollpflichtig vorzuschreiben: 10 km/h beim Befahren gegen die Spitze, 40 km/h beim Befahren von der Wurzel aus."
add("4.5","Fehlende Überwachung Signale","Was ist gemäss § die Folge, wenn die elektrische Überwachung der Endlage einer Weiche fehlt?","Die zugehörigen Signale können nicht auf Fahrt gestellt werden.",["Die Signale zeigen Fahrt mit Vorsicht.","Die Weiche wird automatisch gesperrt.","Die Signale erlöschen."],F)
add("4.5","Wer kontrolliert Endlage","Wen kann der FDL gemäss § mit der örtlichen Kontrolle der korrekten Endlage beauftragen?","Technisches oder fahrdienstliches Personal.",["Nur den technischen Dienst.","Nur den LF des nächsten Zuges.","Nur den RL."],F)
add("4.5","Kontrolle wiederholen","Wann ist die örtliche Kontrolle der Endlage gemäss § zu wiederholen?","Bei Fahrt von der Wurzel aus nach jedem Umstellen der Weiche, bei Fahrt gegen die Spitze vor jeder Fahrt.",["Vor jeder Fahrt in beiden Richtungen.","Nur einmal pro Betriebstag.","Nach jeder dritten Fahrt."],F)
add("4.5","Befund unklar","Was gilt gemäss §, wenn die Weiche mechanisch nicht in der Endlage, beschädigt oder der Befund unklar ist?","Sie darf nicht mehr befahren werden.",["Sie darf mit höchstens 40 km/h befahren werden.","Sie darf mit Fahrt auf Sicht befahren werden.","Sie darf nur gegen die Spitze befahren werden."],F)
add("4.5","Kontrolle durch LF","Was hat der FDL gemäss § dem LF vorzuschreiben, wenn die örtliche Weichenkontrolle dem Personal auf dem Zug übertragen wird?","Quittungspflichtig einen Halt vor der Weiche mit dem Auftrag zur Kontrolle der Weiche.",["Protokollpflichtig Fahrt auf Sicht bis zur Weiche.","Quittungspflichtig die Durchfahrt mit 10 km/h.","Protokollpflichtig die Weiterfahrt ohne Halt."],F)
add("4.5","Geschwindigkeit gegen die Spitze","Mit welcher Höchstgeschwindigkeit darf eine Weiche bei fehlender Überwachung gemäss § bis zur Kontrolle durch den technischen Dienst gegen die Spitze befahren werden?","10 km/h.",["20 km/h.","40 km/h.","60 km/h."],F)
add("4.5","Geschwindigkeit von der Wurzel","Mit welcher Höchstgeschwindigkeit darf eine Weiche bei fehlender Überwachung gemäss § bis zur Kontrolle durch den technischen Dienst von der Wurzel aus befahren werden?","40 km/h.",["10 km/h.","20 km/h.","60 km/h."],F)
F="Das Aufschneiden von Weichen ist verboten, da es betriebsgefährdende Beschädigungen zur Folge haben kann."
add("4.6.1","Aufschneiden verboten","Warum ist das Aufschneiden von Weichen gemäss § verboten?","Weil es betriebsgefährdende Beschädigungen zur Folge haben kann.",["Weil es die Fahrzeit verlängert.","Weil es die Zugbeeinflussung stört.","Weil es nur mit Sondergenehmigung möglich ist."],F)
F="Wurde eine Weiche aufgeschnitten, sind gefährdete Fahrten sofort aufzuhalten und die Beteiligten sind umgehend zu verständigen. Die Weiche ist zu sichern und muss von der Wurzel Richtung Spitze freigelegt werden. Die Weiche ist auf mechanische Schäden zu kontrollieren. Wurde eine Zahnstangenweiche aufgeschnitten, ist sofort anzuhalten und die Weiche zu sichern. Das weitere Vorgehen richtet sich nach den Weisungen des zuständigen technischen Dienstes."
addm("4.6.2","Weiche aufgeschnitten","Was ist gemäss § zu tun, wenn eine Weiche aufgeschnitten wurde (Mehrfachauswahl).",["Gefährdete Fahrten sofort aufhalten","Die Beteiligten umgehend verständigen","Die Weiche sichern","Die Weiche auf mechanische Schäden kontrollieren"],["Die Weiche sofort wieder befahren","Die Weiche erst nach Dienstschluss kontrollieren"],F)
add("4.6.2","Weiche freilegen","In welcher Richtung muss eine aufgeschnittene Weiche gemäss § freigelegt werden?","Von der Wurzel Richtung Spitze.",["Von der Spitze Richtung Wurzel.","Von beiden Enden gleichzeitig.","Nur im abzweigenden Strang."],F)
add("4.6.2","Zahnstangenweiche","Was ist gemäss § zu tun, wenn eine Zahnstangenweiche aufgeschnitten wurde?","Sofort anhalten und die Weiche sichern.",["Mit höchstens 40 km/h weiterfahren.","Mit Fahrt auf Sicht weiterfahren.","Die Weiche durch den LF kontrollieren lassen."],F)
F="Die Kontrolle einer aufgeschnittenen Weiche hat grundsätzlich durch den zuständigen technischen Dienst zu erfolgen. Ist eine sofortige Kontrolle durch den zuständigen technischen Dienst nicht möglich, darf die Weiche mit einer Höchstgeschwindigkeit von 40 km/h befahren werden, sofern sie durch fahrdienstliches Personal kontrolliert wurde und dabei in beiden Lagen keine Schäden festgestellt wurden. Die Verminderung der Geschwindigkeit hat der FDL dem LF protokollpflichtig vorzuschreiben. Am Stellwerk kann der Normalzustand hergestellt werden. Fehlt nach der Durchführung dieser Massnahmen die Weichenüberwachung, ist nach den Bestimmungen über fehlende Weichenüberwachung zu verfahren."
add("4.6.3","Kontrolle aufgeschnittene Weiche","Wer kontrolliert eine aufgeschnittene Weiche gemäss § grundsätzlich?","Der zuständige technische Dienst.",["Der FDL.","Der LF.","Der RL."],F)
addm("4.6.3","Befahren ohne technischen Dienst","Unter welchen Bedingungen darf eine aufgeschnittene Weiche gemäss § bei nicht möglicher sofortiger Kontrolle durch den technischen Dienst mit 40 km/h befahren werden (Mehrfachauswahl).",["Die Weiche wurde durch fahrdienstliches Personal kontrolliert","Es wurden in beiden Lagen keine Schäden festgestellt","Der FDL schreibt dem LF die Geschwindigkeit protokollpflichtig vor"],["Die Weiche wird nur gegen die Spitze befahren","Der LF hat die Weiche selbst umgestellt"],F)
F="Ist die Weiche mechanisch beschädigt oder ist der Befund unklar, darf sie nicht mehr befahren werden. Das weitere Vorgehen richtet sich nach den Weisungen des zuständigen technischen Dienstes. Wird durch den zuständigen technischen Dienst keine Beschädigung der Weiche festgestellt, kann sie wieder normal befahren werden."
add("4.6.5","Weiche nicht beschädigt","Wann kann eine aufgeschnittene Weiche gemäss § wieder normal befahren werden?","Wenn der zuständige technische Dienst keine Beschädigung festgestellt hat.",["Wenn der FDL die Weiche als in Ordnung beurteilt.","Nach der ersten Fahrt mit 40 km/h.","Nach 24 Stunden."],F)
F="Die ISB legt allenfalls in den Ausführungsbestimmungen die Massnahmen über das Verkeilen einer Weiche fest."
add("4.7","Verkeilen","Wer legt gemäss § allenfalls die Massnahmen über das Verkeilen einer Weiche fest?","Die ISB in den Ausführungsbestimmungen.",["Der FDL im Einzelfall.","Das EVU.","Der technische Dienst."],F)
# ---- 7.1 Bahnübergänge
F="Bei einer gestörten überwachten Bahnübergangsanlage bleibt das Hauptsignal auf Halt oder das Kontrolllicht dunkel. Wird eine Bahnübergangsanlage durch äussere Einwirkungen mechanisch beschädigt, haben sich die Beteiligten über das weitere Vorgehen abzusprechen."
addm("7.1.1","Gestörte Bahnübergangsanlage","Woran ist eine gestörte überwachte Bahnübergangsanlage gemäss § erkennbar (Mehrfachauswahl).",["Das Hauptsignal bleibt auf Halt","Das Kontrolllicht bleibt dunkel"],["Das Hauptsignal zeigt Fahrt mit Vorsicht","Die Schranken öffnen sich selbständig"],F)
add("7.1.1","Mechanische Beschädigung BÜ","Was haben die Beteiligten gemäss § zu tun, wenn eine Bahnübergangsanlage durch äussere Einwirkungen mechanisch beschädigt wird?","Sich über das weitere Vorgehen absprechen.",["Den Bahnübergang sofort sperren.","Den technischen Dienst allein entscheiden lassen.","Mit Fahrt auf Sicht weiterfahren."],F)
F="Bei einer mittels Hauptsignal überwachten und gestörten Bahnübergangsanlage kommt der Kernprozess Störungen zur Anwendung. Ausgenommen sind Hauptsignale, an welchen die Zustimmung zur Vorbeifahrt mittels Hauptsignal gestörte Bahnübergangsanlage erteilt wird. Wird die Zustimmung zur Vorbeifahrt mittels Hauptsignal gestörte Bahnübergangsanlage erteilt, sind die Bestimmungen für das Befahren einer gestörten überwachten Bahnübergangsanlage anzuwenden. Bis zum letzten gestörten Bahnübergang der überwachten Bahnübergangsanlage beträgt die Höchstgeschwindigkeit 60 km/h. Unabhängig davon beträgt die Höchstgeschwindigkeit über Weichen im Bahnhof und über Weichen auf der Strecke 40 km/h. Trifft der LF auf ein dunkles Kontrolllicht oder spricht die Zugbeeinflussung an, sind die Bestimmungen für das Befahren einer gestörten überwachten Bahnübergangsanlage anzuwenden. Stellt der LF ein dunkles Kontrolllicht fest oder spricht die Zugbeeinflussung an und wurde der LF darüber nicht verständigt, hat der LF die Störung spätestens nach dem Befahren des letzten Bahnübergangs der gestörten überwachten Bahnübergangsanlage dem FDL zu melden. Der FDL verständigt die folgenden Züge quittungspflichtig über das dunkle Kontrolllicht oder die gestörte Zugbeeinflussung."
add("7.1.2","Kernprozess Hauptsignal","Was kommt gemäss § bei einer mittels Hauptsignal überwachten und gestörten Bahnübergangsanlage zur Anwendung?","Der Kernprozess Störungen.",["Nur die Bestimmungen für das Befahren gestörter Bahnübergänge.","Die Bestimmungen über Fahrt auf Sicht ohne Befehl.","Die Bestimmungen über Weichenstörungen."],F)
add("7.1.2","Höchstgeschwindigkeit BÜ","Wie hoch ist die Höchstgeschwindigkeit gemäss § bis zum letzten gestörten Bahnübergang, wenn die Zustimmung mittels Hauptsignal gestörte Bahnübergangsanlage erteilt wird?","60 km/h.",["40 km/h.","30 km/h.","80 km/h."],F)
add("7.1.2","Höchstgeschwindigkeit Weichen","Wie hoch ist die Höchstgeschwindigkeit über Weichen im Bahnhof und auf der Strecke gemäss § unabhängig davon?","40 km/h.",["60 km/h.","30 km/h.","20 km/h."],F)
add("7.1.2","Dunkles Kontrolllicht melden","Wann hat der LF gemäss § ein nicht angekündigtes dunkles Kontrolllicht dem FDL spätestens zu melden?","Nach dem Befahren des letzten Bahnübergangs der gestörten überwachten Bahnübergangsanlage.",["Vor dem Befahren des ersten Bahnübergangs.","Im nächsten Bahnhof.","Nach Fahrtende."],F)
add("7.1.2","Folgende Züge verständigen","Wie verständigt der FDL die folgenden Züge gemäss § über das dunkle Kontrolllicht oder die gestörte Zugbeeinflussung?","Quittungspflichtig.",["Protokollpflichtig.","Mündlich ohne Quittung.","Gar nicht, die LF erkennen es selbst."],F)
F="Ein überwachter Bahnübergang ohne örtliche Bewachung ist vom LF wie folgt zu befahren: die Geschwindigkeit ist vor dem Befahren des Übergangs auf Schritttempo zu vermindern, nötigenfalls ist anzuhalten; Achtungssignale abgeben und mit dem vordersten Fahrzeug auf den Bahnübergang fahren; auf die zulässige Geschwindigkeit beschleunigen, sobald das erste Fahrzeug den Bahnübergang befahren hat. Ein überwachter Bahnübergang mit örtlicher Bewachung darf mit der zulässigen Höchstgeschwindigkeit befahren werden."
addm("7.1.3","Befahren ohne Bewachung","Wie ist ein gestörter überwachter Bahnübergang ohne örtliche Bewachung gemäss § vom LF zu befahren (Mehrfachauswahl).",["Die Geschwindigkeit vor dem Übergang auf Schritttempo vermindern, nötigenfalls anhalten","Achtungssignale abgeben","Mit dem vordersten Fahrzeug auf den Bahnübergang fahren","Beschleunigen, sobald das erste Fahrzeug den Bahnübergang befahren hat"],["Mit der zulässigen Höchstgeschwindigkeit durchfahren","Erst nach dem Passieren des letzten Fahrzeugs beschleunigen"],F)
add("7.1.3","Befahren mit Bewachung","Wie darf ein überwachter Bahnübergang mit örtlicher Bewachung gemäss § befahren werden?","Mit der zulässigen Höchstgeschwindigkeit.",["Mit Schritttempo.","Mit höchstens 40 km/h.","Mit Fahrt auf Sicht."],F)
F="Bevor eine Fahrt den Abschnitt mit der gestörten überwachten Bahnübergangsanlage befahren darf, hat der FDL die zuständige Person, welche den Bahnübergang örtlich bewacht, über die bevorstehende Abfahrt zu verständigen. Vor dem Erteilen der Zustimmung hat der FDL von der zuständigen Person die Bestätigung einzuholen, dass das Aufhalten des Strassenverkehrs gewährleistet ist. Der FDL hat den LF quittungspflichtig über den gestörten überwachten Bahnübergang sowie die örtliche Bewachung zu verständigen. Diese Verständigung entfällt, wenn ein Zug auf Grund einer Störung mit Fahrt auf Sicht zu verkehren hat."
addm("7.1.4","Verständigung Bewachung","Was hat der FDL gemäss § bei örtlicher Bewachung des Bahnübergangs zu tun (Mehrfachauswahl).",["Die zuständige Person über die bevorstehende Abfahrt verständigen","Vor der Zustimmung die Bestätigung einholen, dass das Aufhalten des Strassenverkehrs gewährleistet ist","Den LF quittungspflichtig über den gestörten Bahnübergang und die örtliche Bewachung verständigen"],["Den Strassenverkehr selbst aufhalten","Den LF protokollpflichtig mit Befehl 9 verständigen"],F)
add("7.1.4","Verständigung entfällt","Wann entfällt die Verständigung des LF über den gestörten Bahnübergang und die örtliche Bewachung gemäss §?","Wenn ein Zug auf Grund einer Störung mit Fahrt auf Sicht zu verkehren hat.",["Wenn der Bahnübergang nachts nicht benützt wird.","Wenn der LF die Strecke kennt.","Wenn die Bewachung durch die Polizei erfolgt."],F)
F="Schaltet die überwachte Bahnübergangsanlage nicht mit der automatischen Steuerung aus, dürfen die Schranken mit der Notbedienung in die Stellung offen verbracht bzw. die Blinklichtanlage manuell ausgeschaltet werden, wenn sich kein Schienenfahrzeug auf dem Bahnübergang befindet; sich kein Schienenfahrzeug gegen den Bahnübergang bewegt; kein Signal bzw. keine Zustimmung eine Fahrt über den Bahnübergang erlaubt; ein Deckungssignal nicht vorgängig mit Nothalt auf Halt gestellt werden kann und die obgenannten Bedingungen erfüllt sind."
addm("7.1.5","Ausschalten Bahnübergangsanlage","Unter welchen Bedingungen dürfen die Schranken gemäss § mit der Notbedienung in die Stellung offen verbracht werden (Mehrfachauswahl).",["Es befindet sich kein Schienenfahrzeug auf dem Bahnübergang","Es bewegt sich kein Schienenfahrzeug gegen den Bahnübergang","Kein Signal bzw. keine Zustimmung erlaubt eine Fahrt über den Bahnübergang"],["Der Strassenverkehr ist durch die Polizei gesperrt","Der LF hat den Bahnübergang bereits befahren"],F)
# ---- 8 Fahrbahn
F="Wird dem FDL eine Unregelmässigkeit an der Fahrbahn (Schienenbruch, Gleisverwerfung, Unterspülung, usw.) gemeldet, hat der FDL folgende Abklärungen zu treffen: Ort der Schadenstelle, Art des Schadens."
addm("8.1","Abklärungen Fahrbahn","Welche Abklärungen hat der FDL gemäss § bei einer gemeldeten Unregelmässigkeit an der Fahrbahn zu treffen (Mehrfachauswahl).",["Ort der Schadenstelle","Art des Schadens"],["Ursache des Schadens","Anzahl betroffener Züge"],F)
F="Der FDL hat: den betreffenden Abschnitt zu sichern; den technischen Dienst zu verständigen; nach Möglichkeit den betreffenden Abschnitt zu umfahren. Ist eine Umfahrung nicht möglich, hat der FDL abzuklären, ob die betreffende Stelle noch befahren werden kann. Kann die betreffende Stelle nicht mehr befahren werden, hat der FDL den Abschnitt zu sperren. Wird die Stelle als befahrbar beurteilt oder kann die Befahrbarkeit nicht beurteilt werden, hat der FDL die weiteren Fahrten gemäss den nachstehenden Bestimmungen über die betreffende Stelle verkehren zu lassen."
addm("8.1.1","Massnahmen Fahrbahn","Welche Massnahmen hat der FDL gemäss § bei einer Unregelmässigkeit an der Fahrbahn zu treffen (Mehrfachauswahl).",["Den betreffenden Abschnitt sichern","Den technischen Dienst verständigen","Den Abschnitt nach Möglichkeit umfahren"],["Den Abschnitt zuerst mit Höchstgeschwindigkeit befahren lassen","Den technischen Dienst erst nach der ersten Fahrt verständigen"],F)
add("8.1.1","Abschnitt sperren","Wann hat der FDL den Abschnitt gemäss § zu sperren?","Wenn die betreffende Stelle nicht mehr befahren werden kann.",["Bei jeder gemeldeten Unregelmässigkeit.","Wenn die Befahrbarkeit nicht beurteilt werden kann.","Wenn der LF es wünscht."],F)
F="Der FDL schreibt der nächsten Fahrt protokollpflichtig Fahrt auf Sicht und höchstens 10 km/h über die betreffende Stelle vor. Bestätigt der LF den Schaden, sperrt der FDL das Gleis. Stellt der LF keinen Schaden fest, schreibt der FDL den LF der nächsten Fahrten protokollpflichtig eine Höchstgeschwindigkeit von 40 km/h über die betreffende Stelle vor. Solange keine Langsamfahrsignale aufgestellt sind, ist zusätzlich gemäss den Bestimmungen «Langsamfahrsignale nicht aufgestellt» vorzugehen. Dies gilt so lange, bis der technische Dienst die Stelle beurteilt und den FDL über das weitere Vorgehen verständigt hat."
add("8.1.2","Nächste Fahrt Fahrbahn","Was schreibt der FDL der nächsten Fahrt gemäss § über die betreffende Stelle protokollpflichtig vor?","Fahrt auf Sicht und höchstens 10 km/h.",["Fahrt auf Sicht und höchstens 40 km/h.","Schritttempo und höchstens 5 km/h.","Höchstens 20 km/h ohne Fahrt auf Sicht."],F)
add("8.1.2","LF bestätigt Schaden","Was tut der FDL gemäss §, wenn der LF den Schaden bestätigt?","Er sperrt das Gleis.",["Er lässt weitere Fahrten mit 10 km/h verkehren.","Er lässt weitere Fahrten mit 40 km/h verkehren.","Er wartet auf die nächste Meldung."],F)
add("8.1.2","LF stellt keinen Schaden fest","Welche Höchstgeschwindigkeit schreibt der FDL den LF der nächsten Fahrten gemäss § vor, wenn der LF keinen Schaden feststellt?","40 km/h.",["10 km/h.","20 km/h.","60 km/h."],F)
add("8.1.2","Bis wann Einschränkung","Bis wann gelten die Einschränkungen über die betreffende Stelle gemäss §?","Bis der technische Dienst die Stelle beurteilt und den FDL über das weitere Vorgehen verständigt hat.",["Bis zum nächsten Tag.","Bis zur dritten Fahrt.","Bis der LF die Stelle als in Ordnung meldet."],F)
# ---- 9 Fahrleitung
F="Wird dem FDL eine Unregelmässigkeit an der Fahrleitung (Spurhalter defekt, Fahrdraht hängt herunter, usw.) gemeldet, hat der FDL folgende Abklärungen zu treffen: Ort der Schadenstelle, Art des Schadens."
add("9.1","Abklärungen Fahrleitung","Welche Abklärungen hat der FDL gemäss § bei einer gemeldeten Unregelmässigkeit an der Fahrleitung zu treffen?","Ort der Schadenstelle und Art des Schadens.",["Nur den Ort der Schadenstelle.","Ursache und Dauer der Unterbrechung.","Anzahl betroffener Züge und Reisender."],F)
F="Stellt der LF Schäden an der Fahrleitung fest, hat der LF sofort die Stromabnehmer zu senken und sofern nötig anzuhalten; darf der LF die Fahrt nur fortsetzen, wenn sichergestellt ist, dass die Stromabnehmer nicht und die Fahrleitung nicht zusätzlich beschädigt werden; und kann der LF nicht mehr weiterfahren, muss der LF beurteilen, ob durch die heruntergerissene Fahrleitung oder herunterhängende Fahrleitungsteile eine unmittelbare Gefahr besteht. Bei Gefahr trifft der LF die notwendigen Massnahmen, damit die Reisenden den Zug nicht verlassen, und zwar bis die zuständigen Mitarbeitenden die entsprechenden Sicherungsmassnahmen vorgenommen haben. Erst wenn keine Gefahr mehr besteht, darf mit der Evakuierung des Zuges begonnen werden. Der FDL hat: den betreffenden Abschnitt zu sichern; den technischen Dienst zu verständigen; nach Möglichkeit den betreffenden Abschnitt zu umfahren. Ist eine Umfahrung nicht möglich, hat der FDL abzuklären, ob die betreffende Stelle noch befahren werden kann. Kann die betreffende Stelle nicht mehr befahren werden, hat der FDL den Abschnitt zu sperren. Wird die Stelle als befahrbar beurteilt oder kann die Befahrbarkeit nicht beurteilt werden, ist das Verkehren einer weiteren Fahrt nur erlaubt, wenn davon ausgegangen werden kann, dass keine zusätzlichen Unregelmässigkeiten verursacht werden und die Fahrt nicht gefährdet wird."
add("9.1.1","LF Schaden Fahrleitung","Was hat der LF gemäss § sofort zu tun, wenn er Schäden an der Fahrleitung feststellt?","Die Stromabnehmer senken und sofern nötig anhalten.",["Die Stromabnehmer gehoben lassen und weiterfahren.","Den Zug evakuieren.","Die Zugsammelschiene einschalten."],F)
add("9.1.1","Fahrt fortsetzen","Unter welcher Voraussetzung darf der LF die Fahrt nach festgestellten Fahrleitungsschäden gemäss § fortsetzen?","Wenn sichergestellt ist, dass die Stromabnehmer nicht und die Fahrleitung nicht zusätzlich beschädigt werden.",["Wenn der FDL zugestimmt hat.","Wenn die Fahrleitung spannungslos ist.","Wenn die Reisenden ausgestiegen sind."],F)
add("9.1.1","Evakuierung","Wann darf gemäss § mit der Evakuierung des Zuges begonnen werden, wenn der LF nicht mehr weiterfahren kann?","Erst wenn keine Gefahr mehr besteht.",["Sofort nach dem Anhalten.","Sobald der FDL verständigt ist.","Sobald die Stromabnehmer gesenkt sind."],F)
add("9.1.1","Reisende zurückhalten","Was hat der LF gemäss § bei unmittelbarer Gefahr durch heruntergerissene Fahrleitungsteile zu tun?","Die notwendigen Massnahmen treffen, damit die Reisenden den Zug nicht verlassen, bis die Sicherungsmassnahmen vorgenommen wurden.",["Die Reisenden sofort evakuieren.","Die Reisenden zum Aussteigen auffordern.","Die Fahrleitung selbst erden."],F)
add("9.1.1","Weitere Fahrt erlaubt","Wann ist gemäss § das Verkehren einer weiteren Fahrt über eine als befahrbar beurteilte Stelle der Fahrleitung nur erlaubt?","Wenn davon ausgegangen werden kann, dass keine zusätzlichen Unregelmässigkeiten verursacht werden und die Fahrt nicht gefährdet wird.",["Wenn der LF die Strecke kennt.","Immer, sofern die Stromabnehmer gehoben sind.","Wenn der technische Dienst eingetroffen ist."],F)
F="Die nächste Fahrt darf die betreffende Stelle nur mit gesenkten Stromabnehmern oder thermisch geführt befahren. Beurteilt der LF die betreffende Stelle als nicht mehr befahrbar oder kann der LF dies nicht beurteilen, sperrt der FDL das Gleis. Andernfalls dürfen weitere Fahrten mit gesenkten Stromabnehmern oder thermisch geführt die betreffende Stelle befahren. Verkehren die Fahrten mit gesenkten Stromabnehmern, hat der FDL den LF mit dem Befehl 9 protokollpflichtig zu verständigen. Dies gilt so lange, bis der technische Dienst die Stelle beurteilt und den FDL über das weitere Vorgehen verständigt hat."
addm("9.1.2","Nächste Fahrt Fahrleitung","Wie darf die nächste Fahrt die betreffende Stelle der beschädigten Fahrleitung gemäss § befahren (Mehrfachauswahl).",["Mit gesenkten Stromabnehmern","Thermisch geführt"],["Mit gehobenen Stromabnehmern und Fahrt auf Sicht","Mit gehobenen Stromabnehmern und höchstens 40 km/h"],F)
add("9.1.2","Befehl 9","Mit welchem Befehl hat der FDL den LF gemäss § zu verständigen, wenn die Fahrten mit gesenkten Stromabnehmern verkehren?","Protokollpflichtig mit dem Befehl 9.",["Quittungspflichtig mit dem Befehl 9.","Protokollpflichtig mit dem Befehl 6.","Quittungspflichtig mit dem Befehl 1."],F)
add("9.1.2","Gleis sperren Fahrleitung","Wann sperrt der FDL das Gleis gemäss § bei beschädigter Fahrleitung?","Wenn der LF die Stelle als nicht mehr befahrbar beurteilt oder dies nicht beurteilen kann.",["Bei jeder gemeldeten Unregelmässigkeit.","Nur wenn die Fahrleitung heruntergerissen ist.","Nach der dritten Fahrt."],F)
F="Stellt der LF fest, dass die Fahrleitung nach einem Spannungsausfall nicht sofort wieder unter Spannung kommt, hat der LF wie folgt vorzugehen: sofort mit Fahrt auf Sicht weiterfahren; nur so lange weiterfahren, dass auf Grund der Bremsbauart noch sicher angehalten werden kann; die Streckentrennung mit gesenktem Stromabnehmer befahren; an geeigneter Stelle, jedoch spätestens im nächsten Bahnhof anhalten. Sobald die Spannung in der Fahrleitung wieder vorhanden ist, darf der LF die Fahrt ohne Einschränkung fortsetzen. Kann der LF nicht feststellen, ob die Spannung in der Fahrleitung wieder vorhanden ist, hat der LF mit dem FDL Kontakt aufzunehmen. Stellt der FDL einen Spannungsausfall fest, darf der FDL keine Zustimmung in den spannungslosen Abschnitt erteilen bzw. hat der FDL eine bereits erteilte Zustimmung zurückzunehmen."
addm("9.2","Fahrleitung spannungslos LF","Wie hat der LF gemäss § vorzugehen, wenn die Fahrleitung nach einem Spannungsausfall nicht sofort wieder unter Spannung kommt (Mehrfachauswahl).",["Sofort mit Fahrt auf Sicht weiterfahren","Nur so lange weiterfahren, dass auf Grund der Bremsbauart noch sicher angehalten werden kann","Die Streckentrennung mit gesenktem Stromabnehmer befahren","An geeigneter Stelle, spätestens im nächsten Bahnhof anhalten"],["Mit gehobenem Stromabnehmer die Streckentrennung befahren","Sofort anhalten und den Zug evakuieren"],F)
add("9.2","Spannung wieder vorhanden","Was darf der LF gemäss § tun, sobald die Spannung in der Fahrleitung wieder vorhanden ist?","Die Fahrt ohne Einschränkung fortsetzen.",["Mit Fahrt auf Sicht bis zum nächsten Bahnhof weiterfahren.","Erst nach Zustimmung des FDL weiterfahren.","Mit höchstens 40 km/h weiterfahren."],F)
add("9.2","Spannung nicht feststellbar","Was hat der LF gemäss § zu tun, wenn er nicht feststellen kann, ob die Spannung in der Fahrleitung wieder vorhanden ist?","Mit dem FDL Kontakt aufnehmen.",["Mit gesenktem Stromabnehmer weiterfahren.","Den Zug evakuieren.","Weiterfahren, als wäre die Spannung vorhanden."],F)
add("9.2","FDL Spannungsausfall","Was darf der FDL gemäss § nach festgestelltem Spannungsausfall nicht tun?","Eine Zustimmung in den spannungslosen Abschnitt erteilen; eine bereits erteilte ist zurückzunehmen.",["Den technischen Dienst aufbieten.","Den LF verständigen.","Den Abschnitt sichern."],F)
# ---- 10 Sicherheitseinrichtungen
F="Übermittelt die Zugbeeinflussung unerwartet die Funktion «Halt» oder «Warnung» bei Vorbeifahrt an einem Zustimmung zur Fahrt zeigenden Hauptsignal, hat der LF anzunehmen, dass das Signal gewollt auf Halt zurück gestellt wurde. Der Zug ist unverzüglich anzuhalten. Die Fahrt darf nur mit quittungspflichtiger Zustimmung des FDL fortgesetzt werden."
add("10.1","Zugbeeinflussung Halt","Was hat der LF gemäss § anzunehmen, wenn die Zugbeeinflussung bei Vorbeifahrt an einem Zustimmung zur Fahrt zeigenden Hauptsignal unerwartet «Halt» oder «Warnung» übermittelt?","Dass das Signal gewollt auf Halt zurück gestellt wurde.",["Dass die Zugbeeinflussung gestört ist.","Dass das Signal defekt ist.","Dass der Streckenmagnet falsch eingestellt ist."],F)
add("10.1","Weiterfahrt Zugbeeinflussung","Unter welcher Voraussetzung darf die Fahrt nach unerwartetem Ansprechen der Zugbeeinflussung gemäss § fortgesetzt werden?","Mit quittungspflichtiger Zustimmung des FDL.",["Mit Fahrt auf Sicht ohne Zustimmung.","Mit protokollpflichtigem Befehl 1.","Nach einer Wartezeit von 5 Minuten."],F)
F="Übermittelt die Zugbeeinflussung eine Fehlermeldung beim Überfahren eines Streckengeräts der Zugbeeinflussung, informiert der LF den FDL unter Angabe des Signals und, sofern möglich, der Art des Fehlers. Bis zur Behebung von dauernden Störungen an Streckengeräten hat der FDL die LF quittungspflichtig über das Fehlansprechen bzw. das Nichtansprechen der Zugbeeinflussung zu verständigen. Der LF hat den Zug trotz des Ansprechens der Zugbeeinflussung an einem Zustimmung zur Fahrt zeigenden Hauptsignal nicht anzuhalten. Bahnübergangsanlagen, welche nur durch Zugbeeinflussung überwacht werden, sind als gestört zu betrachten."
add("10.2","Fehlermeldung Streckengerät","Was hat der LF gemäss § dem FDL bei einer Fehlermeldung der Zugbeeinflussung beim Überfahren eines Streckengeräts mitzuteilen?","Das Signal und, sofern möglich, die Art des Fehlers.",["Nur die Uhrzeit des Fehlers.","Nur die Zugnummer.","Die Ursache des Fehlers."],F)
add("10.2","Dauernde Störung Streckengerät","Wie hat der FDL die LF gemäss § bis zur Behebung dauernder Störungen an Streckengeräten zu verständigen?","Quittungspflichtig über das Fehlansprechen bzw. Nichtansprechen der Zugbeeinflussung.",["Protokollpflichtig mit Befehl 9.","Mündlich ohne Quittung.","Gar nicht."],F)
add("10.2","Zug nicht anhalten","Was gilt gemäss § für den LF, wenn die Zugbeeinflussung an einem Zustimmung zur Fahrt zeigenden Hauptsignal bei bekannter Streckengerätestörung anspricht?","Er hat den Zug nicht anzuhalten.",["Er hat den Zug sofort anzuhalten.","Er hat den FDL anzufordern.","Er hat mit Fahrt auf Sicht weiterzufahren."],F)
add("10.2","BÜ nur ZB","Wie sind Bahnübergangsanlagen, die nur durch Zugbeeinflussung überwacht werden, gemäss § bei Störung von Streckengeräten zu betrachten?","Als gestört.",["Als ausgeschaltet.","Als bewacht.","Als in Ordnung."],F)
F="Sofern keine Notwendigkeit besteht, sind Fahrzeuge mit Störungen an der Zugbeeinflussung nicht als Spitzenfahrzeug einzusetzen. Es dürfen keine Fahrzeuge mit Störungen an der Zugbeeinflussung aus der Instandhaltung eingesetzt werden. Versagt auf dem Spitzenfahrzeug die Zugbeeinflussung, hat der LF bei der ersten Gelegenheit einen LF oder entsprechend geprüftes Personal in den Führerstand anzufordern. Mit einem zusätzlichen LF oder entsprechend geprüftem Personal im Führerstand darf mit höchstens 80 km/h gefahren werden. Solange kein zusätzlicher LF oder entsprechend geprüftes Personal im Führerstand anwesend ist, darf mit höchstens 40 km/h gefahren werden. Bahnübergangsanlagen, welche nur durch Zugbeeinflussung überwacht werden, sind als gestört zu betrachten. Das Fahrzeug darf höchstens 6 Stunden ab Störungsbeginn als Spitzenfahrzeug mit einer defekten Zugbeeinflussung in Betrieb sein. Fahrten direkt zum Instandhaltungsstandort sind auch nach 6 Stunden zulässig, unter der Bedingung, dass mit einem zusätzlichen LF oder entsprechend geprüftem Personal und mit höchstens 80 km/h gefahren wird."
add("10.3","Ausfall ZB Anforderung","Was hat der LF gemäss § bei Versagen der Zugbeeinflussung auf dem Spitzenfahrzeug bei der ersten Gelegenheit zu tun?","Einen LF oder entsprechend geprüftes Personal in den Führerstand anfordern.",["Den Zug evakuieren.","Das Fahrzeug sofort abstellen.","Den technischen Dienst in den Führerstand anfordern."],F)
add("10.3","Mit zusätzlichem LF","Mit welcher Höchstgeschwindigkeit darf bei ausgefallener Zugbeeinflussung mit einem zusätzlichen LF oder entsprechend geprüftem Personal im Führerstand gemäss § gefahren werden?","80 km/h.",["40 km/h.","60 km/h.","100 km/h."],F)
add("10.3","Ohne zusätzlichen LF","Mit welcher Höchstgeschwindigkeit darf bei ausgefallener Zugbeeinflussung ohne zusätzlichen LF oder geprüftes Personal im Führerstand gemäss § gefahren werden?","40 km/h.",["60 km/h.","80 km/h.","20 km/h."],F)
add("10.3","Maximale Einsatzdauer ZB","Wie lange darf ein Fahrzeug mit defekter Zugbeeinflussung gemäss § höchstens ab Störungsbeginn als Spitzenfahrzeug in Betrieb sein?","Höchstens 6 Stunden.",["Höchstens 2 Stunden.","Höchstens 12 Stunden.","Höchstens 24 Stunden."],F)
add("10.3","Fahrt zur Instandhaltung ZB","Unter welcher Bedingung sind Fahrten direkt zum Instandhaltungsstandort gemäss § auch nach 6 Stunden zulässig?","Mit einem zusätzlichen LF oder entsprechend geprüftem Personal und mit höchstens 80 km/h.",["Mit höchstens 40 km/h ohne Begleitung.","Mit Fahrt auf Sicht.","Mit Zustimmung des FDL ohne Einschränkung."],F)
F="Sofern keine Notwendigkeit besteht, sind Fahrzeuge mit Störungen an der Sicherheitssteuerung nicht als Spitzenfahrzeug einzusetzen. Es dürfen keine Fahrzeuge mit Störungen an der Sicherheitssteuerung aus der Instandhaltung eingesetzt werden. Versagt auf dem Spitzenfahrzeug die Sicherheitssteuerung, hat der LF bei der ersten Gelegenheit eine zusätzliche Person eines EBU in den Führerstand anzufordern. Der LF instruiert diese Person, wie der Zug im Notfall anzuhalten ist. Solange keine zusätzliche instruierte Person eines EBU im Führerstand anwesend ist, darf mit defekter Sicherheitssteuerung höchstens 60 km/h gefahren werden. Das Fahrzeug darf höchstens 6 Stunden ab Störungsbeginn als Spitzenfahrzeug mit einer defekten Sicherheitssteuerung verkehren. Fahrten direkt zum Instandhaltungsstandort sind auch nach 6 Stunden zulässig, unter der Bedingung, dass zusätzlich eine instruierte Person eines EBU im Führerstand anwesend ist, die den Zug im Notfall anhalten kann."
add("10.4","Ausfall Sicherheitssteuerung","Was hat der LF gemäss § bei Versagen der Sicherheitssteuerung auf dem Spitzenfahrzeug bei der ersten Gelegenheit anzufordern?","Eine zusätzliche Person eines EBU im Führerstand.",["Den technischen Dienst.","Einen zusätzlichen LF zwingend mit Prüfung.","Den FDL im Führerstand."],F)
add("10.4","Instruktion","Was instruiert der LF der zusätzlichen Person gemäss § bei defekter Sicherheitssteuerung?","Wie der Zug im Notfall anzuhalten ist.",["Wie die Zugbeeinflussung zu bedienen ist.","Wie der Zug zu evakuieren ist.","Wie der FDL zu verständigen ist."],F)
add("10.4","Höchstgeschwindigkeit Sicherheitssteuerung","Mit welcher Höchstgeschwindigkeit darf mit defekter Sicherheitssteuerung gemäss § gefahren werden, solange keine zusätzliche instruierte Person im Führerstand ist?","60 km/h.",["40 km/h.","80 km/h.","20 km/h."],F)
F="Versagt auf einer Zahnstangenstrecke eine Sicherheitseinrichtung, hat der LF gegebenenfalls sofort anzuhalten und zu prüfen, ob die Störung behoben werden kann. Funktioniert die Sicherheitseinrichtung wieder, darf der Betrieb fortgesetzt werden. Fällt die Sicherheitseinrichtung weiterhin aus und kann die Störung nicht behoben werden, darf der LF die Fahrt mit der Hälfte der für die Fahrt und die Strecke zulässigen Geschwindigkeit fortsetzen. Reisende sind beim nächstgelegenen geeigneten Ort zu evakuieren. Die Fahrt mit ausgefallener Sicherheitseinrichtung darf höchstens bis zum nächsten Ort fortgesetzt werden, wo der technische Dienst das Fahrzeug untersuchen oder reparieren kann. Funktioniert ein Teil einer Sicherheitseinrichtung bei redundanten Systemen weiterhin, darf der LF die Fahrt mit normaler Geschwindigkeit bis zum nächsten Ort fortsetzen, wo der technische Dienst das Fahrzeug untersuchen oder reparieren kann. Im Weiteren ist nach den Vorgaben der EVU zu verfahren."
add("10.5","Zahnstange Geschwindigkeit","Mit welcher Geschwindigkeit darf der LF die Fahrt gemäss § bei dauerndem Ausfall einer Sicherheitseinrichtung auf einer Zahnstangenstrecke fortsetzen?","Mit der Hälfte der für die Fahrt und die Strecke zulässigen Geschwindigkeit.",["Mit Fahrt auf Sicht.","Mit höchstens 40 km/h.","Mit Schritttempo."],F)
add("10.5","Zahnstange Reisende","Was ist gemäss § mit den Reisenden zu tun, wenn auf einer Zahnstangenstrecke eine Sicherheitseinrichtung dauernd ausfällt?","Sie sind beim nächstgelegenen geeigneten Ort zu evakuieren.",["Sie bleiben bis zum Streckenende im Zug.","Sie werden im Zug durch den ZBE betreut und nicht evakuiert.","Sie sind sofort auszuladen."],F)
add("10.5","Zahnstange redundant","Wie darf der LF gemäss § weiterfahren, wenn bei redundanten Systemen ein Teil der Sicherheitseinrichtung weiterhin funktioniert?","Mit normaler Geschwindigkeit bis zum nächsten Ort, wo der technische Dienst das Fahrzeug untersuchen oder reparieren kann.",["Mit der halben Geschwindigkeit bis zum Streckenende.","Mit Fahrt auf Sicht bis zum nächsten Bahnhof.","Gar nicht, die Fahrt ist sofort zu beenden."],F)
# ---- 11 Fahrzeuge
F="Bei Unregelmässigkeiten an Fahrzeugen, welche Personen, Anlagen oder Fahrzeuge gefährden bzw. beschädigen können, darf die Fahrt weder begonnen noch fortgesetzt werden. Werden Zugkontrolleinrichtungen zur Überwachung des technischen Zustands während der Fahrt eingesetzt, hat die ISB die dazu nötigen Ausführungsbestimmungen zu erlassen."
add("11.1","Grundsatz Fahrzeuge","Was gilt gemäss § bei Unregelmässigkeiten an Fahrzeugen, welche Personen, Anlagen oder Fahrzeuge gefährden bzw. beschädigen können?","Die Fahrt darf weder begonnen noch fortgesetzt werden.",["Die Fahrt darf mit Fahrt auf Sicht fortgesetzt werden.","Die Fahrt darf bis zum nächsten Bahnhof fortgesetzt werden.","Die Fahrt darf mit halber Geschwindigkeit fortgesetzt werden."],F)
add("11.1","Zugkontrolleinrichtungen","Wer erlässt gemäss § die nötigen Ausführungsbestimmungen, wenn Zugkontrolleinrichtungen zur Überwachung des technischen Zustands während der Fahrt eingesetzt werden?","Die ISB.",["Das EVU.","Das BAV.","Der technische Dienst."],F)
F="Wird eine Unregelmässigkeit an einem Fahrzeug festgestellt, hat das verantwortliche Personal, unter Berücksichtigung der massgebenden Betriebsvorschriften, zu entscheiden, ob die Fahrt begonnen bzw. fortgesetzt werden darf. Kann das verantwortliche Personal vor Ort dies nicht selbst entscheiden, hat es den technischen Dienst zur Klärung des weiteren Vorgehens beizuziehen. Die Störungsabklärung bzw. -behebung an Fahrzeugen soll wenn möglich von der gleisabgewandten Seite oder von der Seite mit einem Sicherheits-Zwischenraum erfolgen. Ist dies nicht möglich, ist nach den Bestimmungen «Fehlender Sicherheits-Zwischenraum» vorzugehen."
add("11.2","Entscheid Fahrt","Wer entscheidet gemäss § bei einer festgestellten Unregelmässigkeit an einem Fahrzeug, ob die Fahrt begonnen bzw. fortgesetzt werden darf?","Das verantwortliche Personal unter Berücksichtigung der massgebenden Betriebsvorschriften.",["Immer der FDL.","Immer der technische Dienst.","Der ZVB allein."],F)
add("11.2","Technischer Dienst beiziehen","Wann hat das verantwortliche Personal gemäss § den technischen Dienst beizuziehen?","Wenn es vor Ort nicht selbst entscheiden kann.",["Bei jeder Unregelmässigkeit.","Nur bei Entgleisungen.","Nur nachts."],F)
addm("11.2","Seite der Störungsbehebung","Von welchen Seiten soll die Störungsabklärung bzw. -behebung an Fahrzeugen gemäss § wenn möglich erfolgen (Mehrfachauswahl).",["Von der gleisabgewandten Seite","Von der Seite mit einem Sicherheits-Zwischenraum"],["Von der Seite des Nachbargleises ohne Zwischenraum","Von unten aus der Grube"],F)
add("11.2","Kein Zwischenraum","Nach welchen Bestimmungen ist gemäss § vorzugehen, wenn die Störungsbehebung weder von der gleisabgewandten Seite noch von der Seite mit Sicherheits-Zwischenraum möglich ist?","Nach den Bestimmungen «Fehlender Sicherheits-Zwischenraum».",["Nach den Bestimmungen «Arbeiten im Gleisbereich».","Nach den Bestimmungen «Gefahren des elektrischen Stroms».","Nach den Bestimmungen über Rangierbewegungen."],F)
add("11.3.1","Offene Aussentüren","Was ist gemäss § mit offenen Aussentüren, Seitenwänden und Schiebedächern zu tun?","Sie sind sofort zu schliessen.",["Sie sind bis zum nächsten Bahnhof zu belassen.","Sie sind mit Fahrt auf Sicht zu sichern.","Sie sind beim nächsten Halt zu kontrollieren."],"Offene Aussentüren, Seitenwände und Schiebedächer sind sofort zu schliessen.")
add("11.3.2","Verschobene Ladungen","Was ist gemäss § mit verschobenen Ladungen zu tun?","Sie sind sofort zu richten und zu sichern.",["Sie sind bis zum Zielbahnhof zu belassen.","Sie sind nur zu kennzeichnen.","Sie sind durch den technischen Dienst zu entladen."],"Verschobene Ladungen sind sofort zu richten und zu sichern.")
add("11.3.3","Entgleiste Fahrzeuge","Unter welchen Bedingungen dürfen entgleiste Fahrzeuge nach dem Aufgleisen gemäss § bewegt werden?","Nur mit Zustimmung und gemäss den Anweisungen des technischen Dienstes.",["Mit Zustimmung des FDL und Fahrt auf Sicht.","Mit höchstens 40 km/h.","Ohne Einschränkung."],"Entgleiste Fahrzeuge dürfen nach dem Aufgleisen nur mit Zustimmung und gemäss den Anweisungen des technischen Dienstes bewegt werden.")
F="Ist der LF nicht in der Lage, Scheinwerfer an der Zugspitze zum Leuchten zu bringen, so gilt Folgendes: Bei guten Sichtverhältnissen meldet der LF den Ausfall dem FDL. Der Zug fährt mit maximal zulässiger Geschwindigkeit an die nächstgelegene Stelle, an der der Frontscheinwerfer instand gesetzt oder ausgetauscht oder das Fahrzeug durch ein anderes ersetzt werden kann. Dabei betätigt der LF falls notwendig oder entsprechend den Anweisungen des FDL die Lokpfeife. Bei Dunkelheit oder schlechten Sichtverhältnissen meldet der LF den Ausfall dem FDL. Mit einem an der Zugspitze angebrachten Handscheinwerfer mit weissem Licht darf der Zug an die nächstgelegene Stelle gefahren werden, an der der Frontscheinwerfer instand gesetzt oder ausgetauscht oder das Fahrzeug durch ein anderes ersetzt werden kann. Kann der Zug nur schlecht erkannt werden, ist nötigenfalls die Geschwindigkeit den Sichtverhältnissen angemessen zu reduzieren. Ist kein Handscheinwerfer vorhanden, so darf der Zug die Fahrt nicht fortsetzen, es sei denn, der FDL erteilt entsprechende Anweisungen zur Fortsetzung der Fahrt bis an die nächstgelegene geeignete Stelle, an der die Strecke freigemacht werden kann."
add("11.3.4","Scheinwerfer gute Sicht","Wie darf der Zug bei vollständigem Ausfall der Frontscheinwerfer und guten Sichtverhältnissen gemäss § fahren?","Mit maximal zulässiger Geschwindigkeit an die nächstgelegene Stelle zur Instandsetzung bzw. zum Austausch.",["Mit Fahrt auf Sicht bis zum Zielbahnhof.","Mit höchstens 40 km/h bis zum Zielbahnhof.","Gar nicht, die Fahrt muss sofort enden."],F)
add("11.3.4","Scheinwerfer Dunkelheit","Was ist gemäss § bei Ausfall der Frontscheinwerfer bei Dunkelheit oder schlechten Sichtverhältnissen erforderlich, damit der Zug zur nächstgelegenen Stelle fahren darf?","Ein an der Zugspitze angebrachter Handscheinwerfer mit weissem Licht.",["Ein Handscheinwerfer mit rotem Licht.","Eine Begleitperson im Führerstand.","Eine Handlampe am Zugschluss."],F)
add("11.3.4","Kein Handscheinwerfer","Was gilt gemäss § bei Ausfall der Frontscheinwerfer, wenn bei Dunkelheit kein Handscheinwerfer vorhanden ist?","Der Zug darf die Fahrt nicht fortsetzen, ausser der FDL erteilt entsprechende Anweisungen.",["Der Zug fährt mit Fahrt auf Sicht weiter.","Der Zug fährt mit höchstens 40 km/h weiter.","Der Zug fährt mit Pfeifsignalen weiter."],F)
addm("11.3.4","Meldung und Pfeife","Was hat der LF gemäss § bei vollständigem Ausfall der Frontscheinwerfer zu tun (Mehrfachauswahl).",["Den Ausfall dem FDL melden","Falls notwendig oder entsprechend den Anweisungen des FDL die Lokpfeife betätigen","Bei schlecht erkennbarem Zug die Geschwindigkeit den Sichtverhältnissen angemessen reduzieren"],["Den Zug bis zum Tageslicht abstellen","Die Zugsammelschiene ausschalten"],F)
F="Bei einem Ausfall der Lokpfeife hat der LF den FDL über den Ausfall zu informieren. Bei einem Defekt der Lokpfeife darf der Zug die maximal zulässige Geschwindigkeit nicht überschreiten und muss an die nächstgelegene Stelle fahren, an der die Lokpfeife instand gesetzt oder das betroffene Fahrzeug ausgetauscht werden kann. Der LF muss zum Anhalten des Zuges vor Bahnübergängen bereit sein, an denen die Lokpfeife betätigt werden muss, und darf die Fahrt nur dann fortsetzen, wenn der Bahnübergang gefahrlos befahren werden kann. Betrifft der Defekt ein Mehrklang-Warnsignal und ist noch mindestens einer der Töne funktionstüchtig, so darf die Zugfahrt normal fortgesetzt werden."
add("11.3.5","Lokpfeife Information","Wen hat der LF gemäss § bei einem Ausfall der Lokpfeife zu informieren?","Den FDL.",["Den ZVB.","Den technischen Dienst.","Die Reisenden."],F)
addm("11.3.5","Lokpfeife Vorgehen","Was gilt gemäss § bei einem Defekt der Lokpfeife (Mehrfachauswahl).",["Die maximal zulässige Geschwindigkeit darf nicht überschritten werden","Der Zug muss an die nächstgelegene Stelle zur Instandsetzung oder zum Austausch fahren","Der LF muss vor Bahnübergängen, an denen die Lokpfeife betätigt werden muss, zum Anhalten bereit sein"],["Der Zug muss sofort evakuiert werden","Der Zug darf nur mit Fahrt auf Sicht weiterfahren"],F)
add("11.3.5","Mehrklang-Warnsignal","Wann darf die Zugfahrt bei einem Defekt eines Mehrklang-Warnsignals gemäss § normal fortgesetzt werden?","Wenn noch mindestens einer der Töne funktionstüchtig ist.",["Wenn alle Töne ausgefallen sind.","Wenn der FDL zugestimmt hat.","Wenn der LF die Strecke kennt."],F)
F="Stellt der FDL einen vollständigen Ausfall des Zugschlusssignals fest, so hat der FDL Vorkehrungen zu treffen, um den Zug an einer geeigneten Stelle anzuhalten und den LF zu informieren. Der LF kontrolliert daraufhin die Zugvollständigkeit und setzt das Zugschlusssignal gegebenenfalls instand oder tauscht es aus. Der LF informiert den FDL, wenn der Zug zur Weiterfahrt bereit ist. Andernfalls, wenn keine Instandsetzung möglich ist, darf die Zugfahrt nicht fortgesetzt werden, ausgenommen der FDL und der LF vereinbaren eine Sonderregelung. Wird auf Strecken mit Handrückmeldung oder auf Strecken ohne Block bei Nacht ein unbeleuchtetes Zugschlusssignal festgestellt, hat der FDL die folgenden Bahnhöfe quittungspflichtig zu verständigen."
add("11.3.6","Zugschlusssignal FDL","Was hat der FDL gemäss § bei einem vollständigen Ausfall des Zugschlusssignals zu tun?","Vorkehrungen treffen, um den Zug an einer geeigneten Stelle anzuhalten, und den LF informieren.",["Den Zug sofort evakuieren lassen.","Den Zug mit Fahrt auf Sicht weiterfahren lassen.","Den technischen Dienst zum Zugschluss schicken."],F)
addm("11.3.6","Zugschlusssignal LF","Was tut der LF gemäss § nach dem Anhalten bei einem Ausfall des Zugschlusssignals (Mehrfachauswahl).",["Er kontrolliert die Zugvollständigkeit","Er setzt das Zugschlusssignal gegebenenfalls instand oder tauscht es aus","Er informiert den FDL, wenn der Zug zur Weiterfahrt bereit ist"],["Er fährt ohne Information weiter","Er löst den Zug in zwei Teile auf"],F)
add("11.3.6","Keine Instandsetzung","Was gilt gemäss §, wenn das Zugschlusssignal nicht instand gesetzt werden kann?","Die Zugfahrt darf nicht fortgesetzt werden, ausgenommen FDL und LF vereinbaren eine Sonderregelung.",["Der Zug darf mit Fahrt auf Sicht weiterfahren.","Der Zug darf mit höchstens 40 km/h weiterfahren.","Der Zug darf ohne Einschränkung weiterfahren."],F)
add("11.3.6","Unbeleuchtetes Zugschlusssignal","Wen hat der FDL gemäss § zu verständigen, wenn auf Strecken mit Handrückmeldung oder ohne Block bei Nacht ein unbeleuchtetes Zugschlusssignal festgestellt wird?","Die folgenden Bahnhöfe quittungspflichtig.",["Die folgenden Bahnhöfe protokollpflichtig.","Nur den technischen Dienst.","Die Reisenden im Zug."],F)
F="Fällt der Geschwindigkeitsmesser aus, hat der LF die Geschwindigkeit stark zu reduzieren, damit die zugelassene Höchstgeschwindigkeit nicht überschritten wird. Sofern möglich ermittelt der LF die Geschwindigkeit anhand der Kilometrierung."
add("11.3.7","Geschwindigkeitsmesser","Was hat der LF gemäss § bei Ausfall des Geschwindigkeitsmessers zu tun?","Die Geschwindigkeit stark reduzieren, damit die zugelassene Höchstgeschwindigkeit nicht überschritten wird.",["Mit der zugelassenen Höchstgeschwindigkeit weiterfahren.","Sofort anhalten und den Zug evakuieren.","Mit Fahrt auf Sicht bis zum Zielbahnhof fahren."],F)
add("11.3.7","Geschwindigkeit ermitteln","Anhand wovon ermittelt der LF die Geschwindigkeit gemäss § sofern möglich bei Ausfall des Geschwindigkeitsmessers?","Anhand der Kilometrierung.",["Anhand der Fahrleitungsmasten-Nummern.","Anhand der Signalabstände.","Anhand der Fahrplanzeiten des FDL."],F)
add("11.3.8","Notbremsüberbrückung","Welche Züge dürfen gemäss § Strecken befahren, auf welchen eine Notbremsüberbrückung bzw. Notbremsanforderung vorgeschrieben ist?","Nur Züge mit betriebsbereiter Notbremsüberbrückung bzw. Notbremsanforderung.",["Alle Züge mit Fahrt auf Sicht.","Alle Züge mit zusätzlichem LF.","Nur Züge ohne Reisende."],"Es dürfen nur Züge mit betriebsbereiter Notbremsüberbrückung bzw. Notbremsanforderung Strecken befahren, auf welchen diese vorgeschrieben sind.")
F="Ist gemäss den Betriebsvorschriften der ISB für Züge ein Kommunikationssystem für fernmündliche Übermittlung erforderlich, darf ein Zug im Ausgangsbahnhof mit defektem Kommunikationssystem nicht abfahren; darf ein Zug während der Fahrt so lange weiterfahren, wie die Notfallkommunikation sichergestellt ist oder eine andere Kommunikationsmöglichkeit zwischen FDL und LF besteht. Das Fahrzeug oder das Kommunikationssystem ist bei nächster Gelegenheit auszuwechseln."
add("11.3.9","Kommunikationssystem Ausgangsbahnhof","Was gilt gemäss § für einen Zug mit defektem Kommunikationssystem im Ausgangsbahnhof?","Er darf nicht abfahren.",["Er darf mit Fahrt auf Sicht abfahren.","Er darf mit höchstens 40 km/h abfahren.","Er darf nach Meldung an den FDL abfahren."],F)
add("11.3.9","Kommunikationssystem unterwegs","Wie lange darf ein Zug gemäss § während der Fahrt mit defektem Kommunikationssystem weiterfahren?","So lange, wie die Notfallkommunikation sichergestellt ist oder eine andere Kommunikationsmöglichkeit zwischen FDL und LF besteht.",["Bis zum nächsten Signal.","Höchstens 6 Stunden.","Bis zum Zielbahnhof in jedem Fall."],F)
add("11.3.9","Auswechseln","Wann ist das Fahrzeug oder das Kommunikationssystem gemäss § auszuwechseln?","Bei nächster Gelegenheit.",["Sofort während der Fahrt.","Erst nach 24 Stunden.","Nur bei Dienstschluss."],F)
# ---- 12 Bremsstörung
add("12.1.1","Bremse unbrauchbar","Was ist gemäss § zu tun, wenn die Bremse unterwegs unbrauchbar wird oder der LF eine ungenügende Bremswirkung feststellt?","Der Zug ist so rasch wie möglich anzuhalten.",["Der Zug fährt mit Fahrt auf Sicht weiter.","Der Zug fährt bis zum nächsten Bahnhof weiter.","Der Zug fährt mit halber Geschwindigkeit weiter."],"Wird die Bremse unterwegs unbrauchbar oder stellt der LF während der Fahrt eine ungenügende Bremswirkung fest, ist der Zug so rasch wie möglich anzuhalten.")
add("12.2.1","Bremskupplung","Wann darf der Kupplungshahn der Luftbremse am letzten Fahrzeug des mit der Spitzenlok verbundenen Zugteils nach einer Zugtrennung gemäss § geschlossen werden?","Erst nach Absprache mit dem LF.",["Sofort nach der Zugtrennung.","Nach Zustimmung des FDL.","Nach Eintreffen des technischen Dienstes."],"Nach einer Zugtrennung darf der Kupplungshahn der Luftbremse am letzten Fahrzeug des mit der Spitzenlok verbundenen Zugteils erst nach Absprache mit dem LF geschlossen werden.")
F="Für das Zusammenfahren nach einer Zugtrennung gelten die Vorschriften für Rangierbewegungen. Bei unbegleiteten Zügen darf der LF den Zugteil mit Zustimmung des FDL unter grösster Vorsicht rückwärts bewegen."
add("12.2.2","Zusammenfahren Vorschriften","Welche Vorschriften gelten gemäss § für das Zusammenfahren nach einer Zugtrennung?","Die Vorschriften für Rangierbewegungen.",["Die Vorschriften für Zugfahrten.","Die Vorschriften für Fahrt auf Sicht.","Die Vorschriften für Notfälle."],F)
add("12.2.2","Unbegleitete Züge rückwärts","Unter welcher Bedingung darf der LF bei unbegleiteten Zügen den Zugteil gemäss § rückwärts bewegen?","Mit Zustimmung des FDL unter grösster Vorsicht.",["Mit Zustimmung des ZVB.","Mit Fahrt auf Sicht ohne Zustimmung.","Gar nicht."],F)
F="Der LF hat das weitere Vorgehen mit dem FDL abzusprechen, wenn Zugteile zurückgelassen werden müssen und die Weiterfahrt nur in Teilen möglich ist. Ohne Absprache mit dem FDL darf der LF höchstens bis zum nächsten Hauptsignal weiterfahren, auch wenn dieses Fahrt zeigt. Das Fahrpersonal hat die zurückgelassenen Zugteile gegen Entlaufen zu sichern. Der FDL hat den betreffenden Abschnitt zu sichern."
add("12.2.3","Zugteile zurücklassen","Wie weit darf der LF gemäss § ohne Absprache mit dem FDL höchstens weiterfahren, wenn Zugteile zurückgelassen werden müssen?","Höchstens bis zum nächsten Hauptsignal, auch wenn dieses Fahrt zeigt.",["Bis zum nächsten Bahnhof.","Bis zum nächsten Fahrt zeigenden Hauptsignal.","Höchstens 1 km."],F)
addm("12.2.3","Zurückgelassene Zugteile","Wer hat gemäss § was zu tun, wenn Zugteile zurückgelassen werden (Mehrfachauswahl).",["Das Fahrpersonal sichert die zurückgelassenen Zugteile gegen Entlaufen","Der FDL sichert den betreffenden Abschnitt","Der LF spricht das weitere Vorgehen mit dem FDL ab"],["Der RL sichert die zurückgelassenen Zugteile mit Keilen","Der technische Dienst sperrt den Abschnitt"],F)
add("12.3.1","Ursache nicht feststellbar","Was ist gemäss § durchzuführen, wenn nach einer Bremsstörung die Ursache nicht einwandfrei festgestellt werden kann?","Eine Hauptbremsprobe.",["Eine Bremsprobe auf Wirkung.","Eine Teilbremsprobe.","Eine Sichtkontrolle durch den FDL."],"Kann nach einer Bremsstörung die Ursache nicht einwandfrei festgestellt werden, ist eine Hauptbremsprobe durchzuführen.")
F="Das nachstehende Vorgehen gilt nach einer Bremsstörung; nach einer Zugtrennung; wenn die Kupplungen nach der Zugtrennung wieder verbunden werden können oder für das Abholen zurückgelassener Zugteile. Ist die Störung behoben und müssen keine Bremsen weiterer Fahrzeuge ausgeschaltet werden und kann eine Bremsprobe durchgeführt werden, ist nach dem vorhandenen Bremsverhältnis weiterzufahren; keine Bremsprobe durchgeführt werden, ist nach dem vorhandenen Bremsverhältnis mit halber Geschwindigkeit der Zug- und Bremsreihe gemäss Bremsrechnung, aber mit höchstens 40 km/h weiterzufahren. Unmittelbar nach der Weiterfahrt ist eine Bremsprobe auf Wirkung durchzuführen. Im nächsten geeigneten Bahnhof ist die Bremsprobe nachzuholen."
addm("12.3.2","Anwendungsfälle","In welchen Fällen gilt das Vorgehen bei behobener Störung ohne ausgeschaltete Bremsen weiterer Fahrzeuge gemäss § (Mehrfachauswahl).",["Nach einer Bremsstörung","Nach einer Zugtrennung","Wenn die Kupplungen nach der Zugtrennung wieder verbunden werden können","Für das Abholen zurückgelassener Zugteile"],["Bei jeder Zugfahrt mit Verspätung","Bei einem Wechsel des LF"],F)
add("12.3.2","Ohne Bremsprobe","Wie ist gemäss § weiterzufahren, wenn keine Bremsprobe durchgeführt werden kann?","Mit halber Geschwindigkeit der Zug- und Bremsreihe gemäss Bremsrechnung, aber mit höchstens 40 km/h.",["Mit der vollen Geschwindigkeit der Zug- und Bremsreihe.","Mit Fahrt auf Sicht.","Mit höchstens 60 km/h."],F)
add("12.3.2","Bremsprobe nachholen","Was ist gemäss § nach der Weiterfahrt ohne Bremsprobe durchzuführen?","Unmittelbar nach der Weiterfahrt eine Bremsprobe auf Wirkung, im nächsten geeigneten Bahnhof die Bremsprobe nachholen.",["Nur eine Bremsprobe auf Wirkung im Zielbahnhof.","Eine Hauptbremsprobe sofort unterwegs.","Keine Bremsprobe, wenn die Störung behoben ist."],F)
F="Lässt sich eine Störung nur beheben, indem eine oder mehrere Bremsen ausgeschaltet werden, darf unter folgenden Bedingungen weitergefahren werden: das Bremsverhältnis ist zu überprüfen; die Bedingungen für das Teilbremsverhältnis müssen erfüllt sein. Es ist zusätzlich eine Bremsprobe durchzuführen. Ist dies nicht möglich, das verbleibende Bremsgewicht und das Teilbremsverhältnis jedoch für die tiefste Geschwindigkeit und die massgebende Neigung genügend, darf nach Bremsverhältnis mit halber Geschwindigkeit der Zug- und Bremsreihe gemäss Bremsrechnung, aber mit höchstens 40 km/h bis zum nächsten geeigneten Bahnhof weitergefahren werden, wo die Bremsprobe nachzuholen ist. Unmittelbar nach der Weiterfahrt ist eine Bremsprobe auf Wirkung durchzuführen."
addm("12.3.3","Bremsen ausgeschaltet","Welche Bedingungen müssen gemäss § für die Weiterfahrt erfüllt sein, wenn Bremsen weiterer Fahrzeuge ausgeschaltet werden mussten (Mehrfachauswahl).",["Das Bremsverhältnis ist zu überprüfen","Die Bedingungen für das Teilbremsverhältnis müssen erfüllt sein","Es ist zusätzlich eine Bremsprobe durchzuführen"],["Der Zug muss entladen werden","Der FDL muss die Fahrt protokollpflichtig genehmigen"],F)
F="Das nachstehende Vorgehen gilt für maximal ein ungebremstes Fahrzeug am Zugschluss, wenn die Bremse unterwegs, nach Abfahrt im Ausgangsbahnhof ausgeschaltet werden muss und bis maximal zur nächsten Änderung der Zusammenstellung des Zuges oder bis zu einem Richtungswechsel. Unter folgenden Bedingungen darf weitergefahren werden: das Bremsverhältnis und das Teilbremsverhältnis sind unter Anrechnung der verbleibenden Bremsen zu ermitteln und müssen mindestens für die tiefste Geschwindigkeit und die massgebende Neigung genügen, wobei das Teilbremsverhältnis für das ungebremste Fahrzeug am Zugschluss unter Einbezug von höchstens zwei unmittelbar vorlaufenden Fahrzeugen erfüllt sein muss; die vom Fahrzeug aus bedienbare Feststellbremse eines mit Reisenden besetzten und nicht mit der Luftbremse gebremsten Wagens am Zugschluss ist zu besetzen; das ungebremste Fahrzeug ist mit dem vorlaufenden straff zu kuppeln und die Hauptleitung ist wenn möglich bis zum Zugschluss zu verbinden. Können diese Bedingungen nicht erfüllt werden und befindet sich das Triebfahrzeug talseitig oder der Zug in der Ebene und genügt das verbleibende Bremsverhältnis für die tiefste Geschwindigkeit und das massgebende Gefälle, darf nach Bremsverhältnis mit höchstens 40 km/h bis zum nächsten Bahnhof gefahren werden; befindet sich das Triebfahrzeug bergseitig, ist die Weiterfahrt verboten. Der Zug ist gegen Entlaufen zu sichern."
add("12.3.4","Anzahl ungebremste Fahrzeuge","Für wie viele ungebremste Fahrzeuge am Zugschluss gilt das Vorgehen gemäss §?","Für maximal ein ungebremstes Fahrzeug.",["Für maximal zwei ungebremste Fahrzeuge.","Für maximal drei ungebremste Fahrzeuge.","Für beliebig viele ungebremste Fahrzeuge."],F)
addm("12.3.4","Bedingungen ungebremstes Fahrzeug","Welche Bedingungen gelten gemäss § für die Weiterfahrt mit einem ungebremsten Fahrzeug am Zugschluss (Mehrfachauswahl).",["Bremsverhältnis und Teilbremsverhältnis sind unter Anrechnung der verbleibenden Bremsen zu ermitteln","Die vom Fahrzeug aus bedienbare Feststellbremse eines besetzten, nicht luftgebremsten Wagens am Zugschluss ist zu besetzen","Das ungebremste Fahrzeug ist mit dem vorlaufenden straff zu kuppeln","Die Hauptleitung ist wenn möglich bis zum Zugschluss zu verbinden"],["Das ungebremste Fahrzeug ist locker zu kuppeln","Das ungebremste Fahrzeug ist zu entladen"],F)
add("12.3.4","Teilbremsverhältnis Fahrzeuge","Unter Einbezug von wie vielen unmittelbar vorlaufenden Fahrzeugen muss das Teilbremsverhältnis für das ungebremste Fahrzeug am Zugschluss gemäss § höchstens erfüllt sein?","Höchstens zwei.",["Höchstens eines.","Höchstens drei.","Höchstens fünf."],F)
add("12.3.4","Triebfahrzeug bergseitig","Was gilt gemäss §, wenn die Bedingungen nicht erfüllt werden können und sich das Triebfahrzeug bergseitig befindet?","Die Weiterfahrt ist verboten und der Zug ist gegen Entlaufen zu sichern.",["Der Zug darf mit höchstens 40 km/h weiterfahren.","Der Zug darf mit Fahrt auf Sicht weiterfahren.","Der Zug darf bis zum nächsten Bahnhof weiterfahren."],F)
add("12.3.4","Triebfahrzeug talseitig","Mit welcher Höchstgeschwindigkeit darf gemäss § weitergefahren werden, wenn die Bedingungen nicht erfüllt werden können, das Triebfahrzeug talseitig ist und das Bremsverhältnis genügt?","Mit höchstens 40 km/h bis zum nächsten Bahnhof.",["Mit höchstens 20 km/h.","Mit höchstens 60 km/h.","Mit der vollen Geschwindigkeit der Zug- und Bremsreihe."],F)
add("12.3.5","Bremsprobeanzeige","Von wo aus muss die Bremsprobe im Störungsfall an Fahrzeugen mit Bremsprobeanzeigen im Führerstand gemäss § durchgeführt werden?","Vom Boden aus.",["Vom Führerstand aus.","Vom Zugschluss aus.","Vom Stellwerk aus."],"An Fahrzeugen, bei welchen eine Bremsprobe mit Bremsprobeanzeigen möglich ist, muss die Bremsprobe im Störungsfall vom Boden aus durchgeführt werden.")
add("12.3.6","Zahnradfahrzeuge","Welche Vorschriften gelten gemäss § für die Weiterfahrt nach einer Bremsstörung bei Zahnradfahrzeugen?","Die Vorschriften der EVU.",["Die Vorschriften der ISB.","Die Vorschriften des BAV.","Die Vorschriften für Rangierbewegungen."],"Für die Weiterfahrt nach einer Bremsstörung gelten für Zahnradfahrzeuge die Vorschriften der EVU.")
# ---- 13 Gefährdungen und Unfälle
F="Wird eine Gefährdung oder ein Unfall verursacht, handelt das Personal in der Reihenfolge: Gefahr erkennen, Auswirkungen abschätzen, Gefahr vermindern, Alarmieren, Retten, Betrieb weiterführen."
add("13.1","Reihenfolge Beginn","Womit beginnt das Personal gemäss § die Reihenfolge des Handelns bei einer Gefährdung oder einem Unfall?","Mit dem Erkennen der Gefahr.",["Mit dem Alarmieren.","Mit dem Retten.","Mit dem Vermindern der Gefahr."],F)
add("13.1","Reihenfolge Alarmieren","Welcher Schritt folgt gemäss § unmittelbar nach «Gefahr vermindern»?","Alarmieren.",["Retten.","Auswirkungen abschätzen.","Betrieb weiterführen."],F)
add("13.1","Reihenfolge Ende","Mit welchem Schritt endet die Reihenfolge des Handelns bei einer Gefährdung oder einem Unfall gemäss §?","Betrieb weiterführen.",["Retten.","Alarmieren.","Auswirkungen abschätzen."],F)
F="Als Gefährdungen im Eisenbahnbetrieb gelten alle Ereignisse, die einen Unfall verursachen oder darauf hinweisen können. Darunter fallen insbesondere: Luftverlust in der Hauptleitung; Entgleisung; Anprall/Zusammenstoss; Zugtrennung; Fahrzeuge entlaufen; Ladungsverschiebung; Nicht erklärbare Unregelmässigkeit im Zuglauf; Zug bleibt ohne ersichtlichen Grund stehen; Unerwartetes Hindernis im Gleisbereich; Gleis/Weiche/Fahrleitung beschädigt; Überfahren eines Halt zeigenden Signals; Notruf oder Alarm erhalten; Freisetzung von gefährlichen Stoffen/Gefahrgut; Naturgefahren (z.B. drohender Erdrutsch, Lawinengefahr)."
add("13.2","Definition Gefährdung","Was gilt gemäss § als Gefährdung im Eisenbahnbetrieb?","Alle Ereignisse, die einen Unfall verursachen oder darauf hinweisen können.",["Nur Ereignisse mit Personenschaden.","Nur Ereignisse mit Sachschaden.","Nur Ereignisse, die zu Verspätungen führen."],F)
addm("13.2","Arten von Gefährdungen 1","Was fällt gemäss § insbesondere unter Gefährdungen (Mehrfachauswahl).",["Luftverlust in der Hauptleitung","Entgleisung","Anprall bzw. Zusammenstoss","Zugtrennung","Fahrzeuge entlaufen","Ladungsverschiebung"],["Verspätung eines Zuges um 5 Minuten","Ausfall der Zugheizung"],F)
addm("13.2","Arten von Gefährdungen 2","Was fällt gemäss § ausserdem insbesondere unter Gefährdungen (Mehrfachauswahl).",["Unerwartetes Hindernis im Gleisbereich","Gleis, Weiche oder Fahrleitung beschädigt","Überfahren eines Halt zeigenden Signals","Notruf oder Alarm erhalten","Freisetzung von gefährlichen Stoffen bzw. Gefahrgut","Naturgefahren, z.B. drohender Erdrutsch oder Lawinengefahr"],["Defekte Anzeigetafel im Bahnhof","Fehlende Reisendeninformation"],F)
F="Als Unfälle im Eisenbahnbetrieb gelten insbesondere Ereignisse mit folgenden Auswirkungen: verletzte oder getötete Personen; verletzte oder getötete grosse Tiere; beschädigte Eisenbahninfrastrukturen; entgleiste oder beschädigte Eisenbahnfahrzeuge; beschädigte Strassenfahrzeuge; Zusammenstösse mit Gegenständen im Gleisbereich, die aufgrund ihrer Grösse oder Beschaffenheit den Eisenbahnbetrieb gefährden können; Brände; mögliche schwere Schädigung von Bevölkerung und Umwelt (z.B. Unregelmässigkeiten mit gefährlichen Stoffen/Gefahrgut)."
addm("13.3","Arten von Unfällen","Welche Ereignisse gelten gemäss § insbesondere als Unfälle im Eisenbahnbetrieb (Mehrfachauswahl).",["Verletzte oder getötete Personen","Verletzte oder getötete grosse Tiere","Beschädigte Eisenbahninfrastrukturen","Entgleiste oder beschädigte Eisenbahnfahrzeuge","Beschädigte Strassenfahrzeuge","Brände"],["Verspätete Züge","Defekte Reisendeninformation"],F)
add("13.3","Zusammenstoss Gegenstände","Wann gelten Zusammenstösse mit Gegenständen im Gleisbereich gemäss § als Unfall?","Wenn die Gegenstände aufgrund ihrer Grösse oder Beschaffenheit den Eisenbahnbetrieb gefährden können.",["Bei jedem Zusammenstoss mit einem Gegenstand.","Nur wenn Personen verletzt werden.","Nur wenn der Zug entgleist."],F)
F="Das Personal, welches eine Gefährdung oder einen Unfall feststellt, hat unter Beachtung des Selbstschutzes unverzüglich dafür zu sorgen, dass die Auswirkungen verringert werden, z.B. indem ein Notruf ausgesendet wird; entlaufene Fahrzeuge aufgehalten werden; der RA Haltbefehle gibt; der SIWÄ das Gleis räumen lässt; das Signal Nothalt auf Arbeitsstellen eingeschaltet wird; der FDL Signale auf Halt stellt, Fahrleitungen ausschaltet, Bahnübergangsanlagen einschaltet, Gleise sichert, Verminderung der Geschwindigkeit anordnet, dem Zug die Fahrt aus dem Tunnel ermöglicht, keine weitere Fahrt in den Tunnel zulässt; der LF den brennenden Zug, allenfalls unter Anwendung der Notbremsüberbrückung, aus dem Tunnel führt; der LF den Zug, allenfalls unter Anwendung der Notbremsüberbrückung, an geeigneter Stelle anhält (z.B. nicht in Tunnels, Galerien oder auf Brücken), das Warnsignal einschaltet, einen Notruf aussendet und die Zugsammelschiene ausschaltet; gefährdete Personen gewarnt werden. Für bestimmte Bauwerke werden durch die ISB spezifische Regelungen aufgrund des Alarm- und Rettungskonzeptes definiert. Diese spezifischen Regelungen haben Vorrang vor den allgemeingültigen Handlungsanweisungen."
add("13.4","Selbstschutz","Was hat das Personal, das eine Gefährdung oder einen Unfall feststellt, gemäss § dabei zu beachten?","Den Selbstschutz.",["Die Weisungen der Medien.","Die Abfahrtszeit des nächsten Zuges.","Die Fahrplanlage."],F)
addm("13.4","FDL Gefahr vermindern","Was kann der FDL gemäss § zur Verminderung der Auswirkungen veranlassen (Mehrfachauswahl).",["Signale auf Halt stellen","Fahrleitungen ausschalten","Bahnübergangsanlagen einschalten","Gleise sichern","Die Geschwindigkeit vermindern lassen","Keine weitere Fahrt in den Tunnel zulassen"],["Die Fahrleitungen einschalten","Den Zug mit Höchstgeschwindigkeit weiterfahren lassen"],F)
addm("13.4","LF Gefahr vermindern","Was hat der LF gemäss § zur Verminderung der Auswirkungen zu tun, wenn er den Zug an geeigneter Stelle anhält (Mehrfachauswahl).",["Das Warnsignal einschalten","Einen Notruf aussenden","Die Zugsammelschiene ausschalten"],["Die Zugsammelschiene eingeschaltet lassen","Den Zug zwingend im Tunnel anhalten"],F)
add("13.4","Brennender Zug","Wohin führt der LF gemäss § den brennenden Zug, allenfalls unter Anwendung der Notbremsüberbrückung?","Aus dem Tunnel.",["In den nächsten Tunnel.","Auf eine Brücke.","In die Galerie."],F)
add("13.4","Spezifische Regelungen","Welchen Vorrang haben die durch die ISB für bestimmte Bauwerke definierten spezifischen Regelungen gemäss §?","Sie haben Vorrang vor den allgemeingültigen Handlungsanweisungen.",["Sie haben nur ergänzenden Charakter.","Sie gelten nur bei Nacht.","Sie haben keinen Vorrang."],F)
F="Das Personal, welches eine Gefährdung oder einen Unfall feststellt, hat unverzüglich den FDL nach dem Prinzip zu verständigen: Wer meldet? Was ist geschehen? Wo ist es geschehen? Wann ist es geschehen? Die ISB erlässt Ausführungsbestimmungen, nach denen der FDL die notwendigen weiteren Massnahmen einzuleiten hat."
addm("13.5","Alarmieren Prinzip","Nach welchem Prinzip hat das Personal den FDL gemäss § zu verständigen (Mehrfachauswahl).",["Wer meldet?","Was ist geschehen?","Wo ist es geschehen?","Wann ist es geschehen?"],["Warum ist es geschehen?","Wie viele Personen sind betroffen?"],F)
add("13.5","Ausführungsbestimmungen Alarm","Wer erlässt gemäss § die Ausführungsbestimmungen, nach denen der FDL die notwendigen weiteren Massnahmen einzuleiten hat?","Die ISB.",["Das EVU.","Das BAV.","Die Polizei."],F)
F="Beim Bergen oder Retten von Personen, Tieren oder Sachen ist dem Schutz der Beteiligten besondere Beachtung zu schenken. Dazu sind beispielsweise Gleise gegen Befahren zu sichern; Verminderung der Geschwindigkeit anzuordnen; Fahrleitungen auszuschalten und zu erden; SIWÄ zu stellen."
addm("13.6","Retten Schutzmassnahmen","Welche Schutzmassnahmen sind beim Bergen oder Retten gemäss § beispielsweise zu treffen (Mehrfachauswahl).",["Gleise gegen Befahren sichern","Verminderung der Geschwindigkeit anordnen","Fahrleitungen ausschalten und erden","SIWÄ stellen"],["Fahrleitungen nur ausschalten, nicht erden","Gleise für Rangierbewegungen freigeben"],F)
F="Sobald Gefährdungen ausgeschlossen sind, von Seiten der zuständigen Dienste keine anders lautenden Weisungen vorliegen und die Untersuchungsorgane die Unfallstelle freigegeben haben, können die Massnahmen zur Verminderung der Gefahr aufgehoben und der Betrieb weitergeführt werden."
addm("13.7","Weiterführen Betrieb","Welche Voraussetzungen müssen gemäss § erfüllt sein, damit der Betrieb weitergeführt werden kann (Mehrfachauswahl).",["Gefährdungen sind ausgeschlossen","Von Seiten der zuständigen Dienste liegen keine anders lautenden Weisungen vor","Die Untersuchungsorgane haben die Unfallstelle freigegeben"],["Die Medien wurden informiert","Der nächste Zug ist bereit"],F)
# ---- 14
F="Bei Erkennung des Warnsignals hat der LF sofort anzuhalten und den Sachverhalt abzuklären. Wird keine Hilfe vor Ort benötigt, ist weiterzufahren, wenn dadurch keine Gefährdung entsteht. Bei unklarem Notruf hat der LF sofort mit Fahrt auf Sicht zu fahren. Die Einfahrt in Tunnels ist zu vermeiden. Der LF hat mit dem FDL Verbindung aufzunehmen. Ist dies nicht möglich und erhält der LF keine anders lautende Weisung, darf die Fahrt nach 10 Minuten ohne diese Einschränkungen fortgesetzt werden."
add("14.1","Warnsignal erkannt","Was hat der LF gemäss § bei Erkennung des Warnsignals zu tun?","Sofort anhalten und den Sachverhalt abklären.",["Mit Fahrt auf Sicht weiterfahren.","Mit höchstens 40 km/h weiterfahren.","Bis zum nächsten Bahnhof weiterfahren."],F)
add("14.1","Warnsignal Weiterfahrt","Wann ist nach Erkennung des Warnsignals gemäss § weiterzufahren?","Wenn keine Hilfe vor Ort benötigt wird und dadurch keine Gefährdung entsteht.",["Sobald der Zug angehalten hat.","Nach 10 Minuten in jedem Fall.","Nach Zustimmung des technischen Dienstes."],F)
addm("14.1","Unklarer Notruf","Was hat der LF gemäss § bei einem unklaren Notruf zu tun (Mehrfachauswahl).",["Sofort mit Fahrt auf Sicht fahren","Die Einfahrt in Tunnels vermeiden","Mit dem FDL Verbindung aufnehmen"],["Sofort anhalten und evakuieren","In Tunnels mit Höchstgeschwindigkeit einfahren"],F)
add("14.1","Unklarer Notruf 10 Minuten","Wann darf die Fahrt nach einem unklaren Notruf gemäss § ohne Einschränkungen fortgesetzt werden, wenn keine Verbindung zum FDL möglich ist?","Nach 10 Minuten, sofern keine anders lautende Weisung vorliegt.",["Nach 5 Minuten.","Nach 30 Minuten.","Sofort."],F)
F="Der LF hat den ZBE und die Reisenden zu verständigen, wenn der LF die Wirkung der Notbremse überbrückt. Die Notbremse darf nur nach Absprache mit dem LF zurückgestellt werden."
add("14.2","Notbremse überbrückt","Wen hat der LF gemäss § zu verständigen, wenn er die Wirkung der Notbremse überbrückt?","Den ZBE und die Reisenden.",["Nur den FDL.","Nur den technischen Dienst.","Niemanden."],F)
add("14.2","Notbremse zurückstellen","Wann darf die Notbremse gemäss § zurückgestellt werden?","Nur nach Absprache mit dem LF.",["Sofort durch den ZBE.","Nach Zustimmung des FDL.","Sobald der Zug steht."],F)
add("14.3","Weiterfahrt vor Hilfe","Wann darf der LF den Zug bzw. die Rangierbewegung gemäss § vor dem Eintreffen der verlangten Hilfe bewegen?","Nur mit Zustimmung des FDL.",["Sobald keine Gefahr mehr besteht.","Nach 10 Minuten.","Mit Zustimmung des ZBE."],"Wurde Hilfe verlangt, darf der LF vor deren Eintreffen den Zug bzw. die Rangierbewegung nur mit Zustimmung des FDL bewegen.")
F="Bei Erkennung des Signals Nothalt auf Arbeitsstellen hat der LF sofort anzuhalten und mit dem FDL Kontakt aufzunehmen. Der FDL klärt mit dem SC die Ursache ab. Erhält der FDL, nach dem Dunkelschalten des Signals, vom SC die Zustimmung zur Weiterfahrt, hat der FDL den LF darüber quittungspflichtig zu verständigen. Ist die Arbeitsstelle nicht besetzt oder kann der FDL mit dem SC keinen Kontakt aufnehmen, hat der FDL dem LF der ersten Fahrt protokollpflichtig Vorbeifahrt am Halt zeigenden Signal Nothalt auf Arbeitsstellen und Fahrt auf Sicht bis zum Ende der Arbeitsstelle vorzuschreiben. Wurde keine Unregelmässigkeit festgestellt, darf das Signal ausgeschaltet werden. Kann das Signal nicht ausgeschaltet werden, hat der FDL die LF protokollpflichtig über das Vorbeifahren am Signal Nothalt auf Arbeitsstellen zu verständigen."
add("14.4","Nothalt erkannt","Was hat der LF gemäss § bei Erkennung des Signals Nothalt auf Arbeitsstellen zu tun?","Sofort anhalten und mit dem FDL Kontakt aufnehmen.",["Mit Fahrt auf Sicht weiterfahren.","Mit dem SC Kontakt aufnehmen und weiterfahren.","Bis zum Ende der Arbeitsstelle weiterfahren."],F)
add("14.4","Nothalt Ursache","Mit wem klärt der FDL gemäss § die Ursache des Signals Nothalt auf Arbeitsstellen ab?","Mit dem SC.",["Mit dem RA.","Mit dem technischen Dienst.","Mit dem SIWÄ."],F)
add("14.4","Nothalt Zustimmung","Wie verständigt der FDL den LF gemäss §, wenn er nach dem Dunkelschalten des Signals vom SC die Zustimmung zur Weiterfahrt erhält?","Quittungspflichtig.",["Protokollpflichtig.","Mündlich ohne Quittung.","Mit Befehl 1."],F)
add("14.4","Nothalt Arbeitsstelle nicht besetzt","Was hat der FDL dem LF der ersten Fahrt gemäss § protokollpflichtig vorzuschreiben, wenn die Arbeitsstelle nicht besetzt ist oder kein Kontakt zum SC möglich ist?","Die Vorbeifahrt am Halt zeigenden Signal Nothalt auf Arbeitsstellen und Fahrt auf Sicht bis zum Ende der Arbeitsstelle.",["Nur Fahrt auf Sicht ohne Vorbeifahrt am Signal.","Halt bis zur Freigabe durch den SC.","Die Vorbeifahrt mit der vorgeschriebenen Höchstgeschwindigkeit."],F)
add("14.4","Signal nicht ausschaltbar","Was hat der FDL gemäss § zu tun, wenn das Signal Nothalt auf Arbeitsstellen nicht ausgeschaltet werden kann?","Die LF protokollpflichtig über das Vorbeifahren am Signal zu verständigen.",["Die LF quittungspflichtig über Halt zu verständigen.","Die Arbeitsstelle sperren zu lassen.","Das Signal bis zur nächsten Fahrt zu belassen und nicht zu verständigen."],F)
F="Die EBU haben die bei Unfällen mit gefährlichen Gütern einzuleitenden Sofortmassnahmen in einem für ihr Personal verbindlichen Merkblatt zu regeln, und zwar in Abstimmung mit den Grundsätzen der Einsatzplanung bei Eisenbahnen gemäss Störfallverordnung (StFV, SR 814.012). Dieses Merkblatt muss insbesondere regeln: den Selbstschutz des Bahnpersonals; das Erkennen von Gefahren (bahn- und stoffspezifische Gefahren); das Melden des Ereignisses (Meldestelle, Meldungsinhalt, Meldebeispiel); weitere Massnahmen (Unfallort sichern, Verletzte bergen, Einsatzkräfte einweisen). Die EBU haben den Verteiler für das Merkblatt festzulegen. Das betroffene Personal muss das Merkblatt auf sich tragen."
add("14.5","Merkblatt gefährliche Güter","Wer hat gemäss § die Sofortmassnahmen bei Unfällen mit gefährlichen Gütern in einem verbindlichen Merkblatt zu regeln?","Die EBU.",["Die ISB.","Das BAV.","Die Feuerwehr."],F)
addm("14.5","Inhalt Merkblatt","Was muss das Merkblatt für Unfälle mit gefährlichen Gütern gemäss § insbesondere regeln (Mehrfachauswahl).",["Den Selbstschutz des Bahnpersonals","Das Erkennen von Gefahren (bahn- und stoffspezifische Gefahren)","Das Melden des Ereignisses","Weitere Massnahmen (Unfallort sichern, Verletzte bergen, Einsatzkräfte einweisen)"],["Die Entschädigung der Geschädigten","Die Fahrplanänderungen nach dem Unfall"],F)
add("14.5","Merkblatt tragen","Was gilt gemäss § für das betroffene Personal bezüglich des Merkblatts?","Es muss das Merkblatt auf sich tragen.",["Es muss es im Depot hinterlegen.","Es muss es nur im Führerstand mitführen.","Es muss es nur auf Verlangen vorweisen."],F)
add("14.5","Merkblatt Grundlage","In Abstimmung mit welchen Grundsätzen sind die Sofortmassnahmen im Merkblatt gemäss § zu regeln?","Mit den Grundsätzen der Einsatzplanung bei Eisenbahnen gemäss Störfallverordnung (StFV).",["Mit den Grundsätzen der Strassenverkehrsgesetzgebung.","Mit den Grundsätzen des Arbeitsgesetzes.","Mit den Grundsätzen des Eisenbahngesetzes."],F)
F="Verletzte Personen dürfen nicht ohne Betreuung zurückgelassen werden. Unter Schock stehende Personen sind soweit möglich zu betreuen. Über Unfallopfer darf nicht gefahren werden. Sie sind zuzudecken und zu bewachen."
addm("14.6","Betroffene Personen","Was gilt gemäss § im Umgang mit betroffenen Personen (Mehrfachauswahl).",["Verletzte Personen dürfen nicht ohne Betreuung zurückgelassen werden","Unter Schock stehende Personen sind soweit möglich zu betreuen","Über Unfallopfer darf nicht gefahren werden","Unfallopfer sind zuzudecken und zu bewachen"],["Unfallopfer sind sofort zu verlegen","Unter Schock stehende Personen sind allein zu lassen"],F)
F="Die notwendigen Sicherungs- und Rettungsarbeiten sind unverzüglich einzuleiten. An der Unfallsituation dürfen sonst keine Veränderungen vorgenommen werden. Dadurch entstehende Änderungen sind zu dokumentieren. Die ursprüngliche Lage der Opfer, der Fahrzeuge und von Gegenständen sind deutlich zu kennzeichnen. Tote dürfen nur mit dem Einverständnis der Strafverfolgungsbehörde geborgen werden. Daten (z.B. Geschwindigkeitsaufzeichnungen, Gesprächsaufzeichnungen, protokollpflichtige Befehle) und Funktionszustände der Sicherungseinrichtungen, die der Klärung der Ursachen und Umstände des Ereignisses dienen könnten, sind von den Verantwortlichen der beteiligten Unternehmen zuhanden der Untersuchungsinstanz zu sichern und während mindestens sechs Monaten aufzubewahren. Die Namen und Adressen von Personen, die sachdienliche Hinweise zum Ablauf des Ereignisses geben könnten, sind festzuhalten. Sobald die Strafverfolgungsbehörde auf der Unfallstelle eintrifft, entscheidet sie über die Art und den Umfang der Sicherungsmassnahmen und die Bewachung."
add("14.7","Veränderungen Unfallsituation","Was gilt gemäss § für Veränderungen an der Unfallsituation, die nicht für Sicherungs- und Rettungsarbeiten nötig sind?","Es dürfen keine Veränderungen vorgenommen werden; unvermeidliche Änderungen sind zu dokumentieren.",["Veränderungen sind jederzeit erlaubt.","Veränderungen sind nur mit Zustimmung der Medien erlaubt.","Veränderungen sind nur zu melden, nicht zu dokumentieren."],F)
add("14.7","Tote bergen","Wann dürfen Tote gemäss § geborgen werden?","Nur mit dem Einverständnis der Strafverfolgungsbehörde.",["Sofort nach dem Unfall.","Mit Zustimmung des FDL.","Mit Zustimmung des technischen Dienstes."],F)
add("14.7","Daten aufbewahren","Wie lange sind Daten und Funktionszustände der Sicherungseinrichtungen zur Klärung des Ereignisses gemäss § mindestens aufzubewahren?","Mindestens sechs Monate.",["Mindestens einen Monat.","Mindestens drei Monate.","Mindestens zwölf Monate."],F)
addm("14.7","Zu sichernde Daten","Welche Daten sind gemäss § zuhanden der Untersuchungsinstanz zu sichern (Mehrfachauswahl).",["Geschwindigkeitsaufzeichnungen","Gesprächsaufzeichnungen","Protokollpflichtige Befehle","Funktionszustände der Sicherungseinrichtungen"],["Fahrausweiskontrollen der Reisenden","Pressemitteilungen"],F)
add("14.7","Wer entscheidet Sicherung","Wer entscheidet gemäss § nach ihrem Eintreffen über die Art und den Umfang der Sicherungsmassnahmen und die Bewachung der Unfallstelle?","Die Strafverfolgungsbehörde.",["Der FDL.","Die ISB.","Der technische Dienst."],F)
add("14.7","Personen festhalten","Was ist gemäss § mit Namen und Adressen von Personen zu tun, die sachdienliche Hinweise zum Ablauf des Ereignisses geben könnten?","Sie sind festzuhalten.",["Sie sind nur auf Verlangen aufzunehmen.","Sie sind den Medien zu übergeben.","Sie sind nicht zu erfassen."],F)
